INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('nature', 'exile', 'exile', 'Exilé', NULL, '{"nature":"exile","description":"Elyë, Whurten, Ashyll, Thulkar et Azménoriens sont les principales communautés venues d’Aèr. Beaucoup vivent sur Terre depuis bien avant l’Hologramme et y sont nés depuis de nombreuses générations : être Exilé ne signifie donc pas nécessairement être un voyageur récemment arrivé. Le peuple décrit une physiologie et un héritage ; réseaux, métiers, factions et traditions restent des choix séparés.","carte":"**EXILÉ · NATURE**. Tu descends d''un peuple venu d''Aèr. Ton peuple est fixé à la création et ne change jamais.\n\n- **Voilé** : l''Hologramme te traduit en humain. Aucun bonus. Les traits marqués V restent actifs.\n- **Semi-Révélé et Révélé** : modificateurs de ton peuple, ci-dessous. Ils ne remplacent jamais tes Attributs bruts.\n\n| Peuple | SR | R | Traits gratuits |\n|---|---|---|---|\n| **Elyë** (elfes) | +1 Agilité | +1 Agilité, +1 Esprit, +1 Charisme | **Ambidextrie naturelle** (SR/R) : aucune pénalité due à la main non dominante, aucune attaque en plus. **Affinité elfique à la Magie** : tu peux apprendre les traditions magiques compatibles, sans aucun sort gratuit. **Longévité** : narratif. |\n| **Whurten** (nains) | +1 Vigueur | +1 Vigueur, +2 Volonté | **Sens magnétique** (V/SR/R) : tu connais toujours le nord magnétique et tu sens les anomalies magnétiques importantes. Esprit + Perception affine la direction, l''intensité ou la source. |\n| **Ashyll** (gobelins) | +1 Agilité | +2 Agilité, +1 Esprit | **Ouïe ashyll** (V/SR/R) : +3 aux perceptions auditives quand un son réel est présent. **Petite morphologie** : tu accèdes aux espaces et aux couverts à ta taille, sans bonus chiffré. |\n| **Thulkar** (orques) | +1 Vigueur | +2 Vigueur, +1 Charisme | Aucun trait listé (question 3). |\n| **Azménorien** | +1 Esprit | +1 Vigueur, +1 Esprit, +1 Charisme | **Ailes sombres** (R) : grands sauts, franchissement vertical, chutes amorties, pas de vol libre. **Don magique azménorien** : accès aux traditions magiques compatibles, sans aucun sort gratuit. |\n\n- **Limite** : un trait ne crée jamais d''action supplémentaire.\n- **Faiblesses** : les sources ne donnent ni faiblesse ni malédiction de Nature aux Exilés.\n- **Maîtrise** : aucune. Le peuple ne change pas et rien ne s''éveille. Une voie de peuple ou de tradition se complète simplement.\n\n**Corrections** :\n- Le tableau des peuples annonce une « physiologie robuste » pour le Whurten, mais aucun trait ne porte ce nom ni ce texte.\n- Le tableau ne donne aucun trait au Thulkar.\n- Ces deux points sont traités à la question 3. La carte reprend les traits tels qu''ils existent.\n\n---","traits_gratuits":[],"droits_acquis":"Les talents achetés avant les voies restent acquis ; les règles de voie valent pour les achats suivants (décision 20)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_elye', 'Elyë', NULL, '{"nature":"exile","chemin":["Voies de peuple","Elyë"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_voies_de_peuple', 'Voies de peuple', NULL, '{"nature":"exile","chemin":["Voies de peuple"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_elye_grace_elfique', 'Grâce elfique', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Effacement elfique : fréquence 1/scène reprise du tableau (le texte l''oubliait). Réflexe de grâce : note de développement retirée (« ne restreint pas silencieusement… »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-pas-leger', 'Pas léger', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Passif","texte_court":"quand tu te déplaces avec prudence, tu ignores jusqu''à −3 dus à un sol étroit, instable, fragile ou bruyant.","texte_reference":"Ignorez jusqu''à -3 de malus de circonstances provenant uniquement d''un sol étroit, instable, fragile ou bruyant lorsque l''Elyë se déplace avec prudence. Le Talent ne permet pas de tenir sur une surface physiquement impossible.","lore":"Le Pas léger répartit poids et équilibre avec une finesse qui rend les supports difficiles étonnamment praticables. Sol fragile, étroit ou bruyant devient moins contraignant tant qu’il existe vraiment quelque chose sur quoi marcher.","groupe_actuel":"Les cinq profils raciaux › Elyë — Elfes › Grace elfique — 5 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-effacement-elfique', 'Effacement elfique', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1/scène","activation":"1/Scène","texte_court":"après un Déplacement qui rompt la ligne de vue ou qui t''amène à couvert, tu tentes ta discrétion sans PA supplémentaire. Il faut un endroit où disparaître.","texte_reference":"Après un Déplacement qui rompt réellement la ligne de vue ou amène l''Elyë dans un couvert permettant de se cacher, il peut immédiatement tenter son’action de discrétion sans dépenser de PA supplémentaire. Si aucun’endroit ne permet de disparaître, le Talent ne crée pas de cachette.","lore":"La Grâce elyë sait transformer un mouvement de fuite en disparition réelle. Dès que couvert et rupture de vue existent, l’Elfe se fond dans l’espace sans perdre une seconde à changer de rythme.","groupe_actuel":"Les cinq profils raciaux › Elyë — Elfes › Grace elfique — 5 PTV","statut_regle":"correction","changements":"Effacement elfique : fréquence 1/scène reprise du tableau (le texte l''oubliait). Réflexe de grâce : note de développement retirée (« ne restreint pas silencieusement… »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-reflexe-de-grace', 'Réflexe de grâce', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"SR/R, 1/scène","activation":"Réaction sans PA supplémentaire — 1/scène","texte_court":"après un échec non narratif en Défense active, relance le d10 et garde le second résultat, sans payer de second PA.","texte_reference":"Une fois par scène, après un échec non narratif à une Défense active, relancez le d10 explosif et conservez le second résultat, sans payer un second PA.\nLa Défense initiale reste payante ; une seule relance de Talent par test. Ne restreint pas silencieusement les types de Défenses admis actuellement.","lore":"Même une esquive manquée peut être reprise par une correction de posture presque instantanée. La Grâce elyë transforme l’erreur en second mouvement avant que l’impact ne devienne inévitable.","groupe_actuel":"Les cinq profils raciaux › Elyë — Elfes › Grace elfique — 5 PTV","statut_regle":"correction","changements":"Effacement elfique : fréquence 1/scène reprise du tableau (le texte l''oubliait). Réflexe de grâce : note de développement retirée (« ne restreint pas silencieusement… »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_elye_memoire_elfique', 'Mémoire elfique', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Lecture des êtres n''avait pas de prérequis. Elle se prend désormais après l''entrée de la voie."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-souvenir-ordonne', 'Souvenir ordonné', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"ce que tu as délibérément observé pendant une scène, tu le rappelles plus tard fidèlement, sans jet (formulation, lieu, visage, séquence, symbole). Jamais ce que tu n''as pas perçu.","texte_reference":"Lorsque l''Elyë a délibérément observé une information concrété pendant une scène, il peut la rappeler plus tard avec une grande fidélité sans jet : formulation’approximative, disposition d''un lieu, visage, séquence d''actions, symbole ou détail comparable. Le Talent ne crée jamais une information qu''il n''a pas perçue.","lore":"Ce que l’Elyë choisit consciemment de retenir reste classé avec une netteté inhabituelle. Visage, symbole, disposition ou séquence d’actions peuvent être rappelés plus tard sans que la mémoire invente ce qui n’a jamais été observé.","groupe_actuel":"Les cinq profils raciaux › Elyë — Elfes › Mémoire elfique — 5 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-experience-accumulee', 'Expérience accumulée', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, 1/scénario","activation":"1/scénario","texte_court":"avant le premier jet, déclare une expérience ancienne plausible. Pour la scène, tu peux tenter les tâches ordinaires du domaine même à Compétence 0, avec +3 aux tests de ce domaine précis. Tu n''obtiens ni secret surnaturel ni diplôme.","texte_reference":"Une fois par scénario, rappelez une expérience ancienne plausible : pour la scène, elle autorise les tâches ordinaires correspondantes même à Compétence 0 et donne +3 aux tests d’un domaine précis lié à cette expérience. Aucun secret surnaturel, diplôme officiel ou talent n’est obtenu.\nL’expérience est définie avant le premier jet ; le bonus bénéficie aussi à un spécialiste, sans augmenter son rang permanent.","lore":"Une longue vie laisse des apprentissages que la fiche de compétences ne raconte pas tous. L’Elyë peut rappeler une expérience plausible ancienne et retrouver assez de familiarité pour agir correctement dans un domaine ordinaire déjà rencontré.","groupe_actuel":"Les cinq profils raciaux › Elyë — Elfes › Mémoire elfique — 5 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-lecture-des-etres', 'Lecture des êtres', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R, 1/scène","activation":"Observation : quelques minutes — 1/scène","texte_court":"après quelques minutes d''échange, le MJ te donne une émotion retenue, une priorité ou un point d''attention. Ton premier test social qui l''exploite gagne +3. Ce n''est pas de la télépathie.","texte_reference":"Après quelques minutes d’interaction, le MJ indique une émotion retenue, une priorité ou un point d’attention déductible des comportements. Une fois par scène, votre premier test social qui exploite directement cette lecture bénéficie de +3.\nPas de télépathie, de vérité automatique sur un menteur ou de bonus sur toutes les interactions.","lore":"Observer longtemps quelqu’un révèle des rythmes que la mémoire elfique sait organiser. Émotion contenue, priorité immédiate ou dynamique sociale deviennent lisibles sans jamais se transformer en lecture de pensée.","groupe_actuel":"Les cinq profils raciaux › Elyë — Elfes › Mémoire elfique — 5 PTV","statut_regle":"correction","changements":"Lecture des êtres n''avait pas de prérequis. Elle se prend désormais après l''entrée de la voie."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_elye_resonance_elfique', 'Résonance elfique', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Accord instinctif ne demandait que Sens du Flux. Il se prend désormais au bout de la voie. Accord instinctif : la clause de non-cumul est réduite à « ne se cumule pas avec Maintien naturel »."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-sens-du-flux', 'Sens du Flux', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Passif — 10 m","texte_court":"tu sens une magie active ou une forte perturbation du Flux à 10 m. Tu n''apprends ni sa source, ni sa puissance, ni la Nature d''un Voilé.","texte_reference":"Ressentez une manifestation magique active ou une forte perturbation du Flux directement perceptible à 10 m maximum. Cela n’identifie ni sa source, ni sa puissance, ni la Nature d’une personne simplement Voilée.","lore":"La magie active possède une tension que l’Elyë ressent avant d’en comprendre la forme. Une forte perturbation proche devient évidente, mais sa source, son domaine et sa puissance restent à découvrir.","groupe_actuel":"Les cinq profils raciaux › Elyë — Elfes › Resonance elfique — 7 PTV","statut_regle":"correction","changements":"Accord instinctif ne demandait que Sens du Flux. Il se prend désormais au bout de la voie. Accord instinctif : la clause de non-cumul est réduite à « ne se cumule pas avec Maintien naturel »."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-empreinte-du-flux', 'Empreinte du Flux', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"SR/R","activation":"Passif","texte_court":"tu mémorises une signature magique que tu as étudiée et tu la reconnais ensuite. Une signature profondément altérée doit être étudiée de nouveau.","texte_reference":"Vous mémorisez une signature magique réellement étudiée et pouvez reconnaître la même source ou empreinte. Une signature profondément altérée doit être réétudiée.","lore":"Une signature magique observée directement laisse une empreinte reconnaissable dans la mémoire elyë. Plus tard, le même Flux ou la même source peut être identifié malgré un contexte différent tant qu’il n’a pas été profondément altéré.","groupe_actuel":"Les cinq profils raciaux › Elyë — Elfes › Resonance elfique — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-suivre-le-flux', 'Suivre le Flux', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":"Actif","texte_court":"Esprit + Perception pour suivre une signature connue qui a laissé des manifestations récentes. Tu retrouves sa direction et les ruptures de piste. Aucune trace n''est créée.","texte_reference":"Une signature magique connue peut être suivie lorsqu’elle a laissé des manifestations récentes et perceptibles dans l''environnement. Esprit + Perception permet d''en retrouver la direction et les ruptures de piste. Le Talent rend possible une traque que des sens ordinaires ne pourraient pas menér, sans creer de trace lorsque la source n''en’a laissé aucune.","lore":"Une magie connue laisse parfois une piste dans le monde : résidu, rupture, direction. L’Elyë suit ces traces comme une succession de résonances récentes, là où des sens ordinaires ne verraient qu’un lieu redevenu calme.","groupe_actuel":"Les cinq profils raciaux › Elyë — Elfes › Resonance elfique — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-accord-instinctif', 'Accord instinctif', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1/scène","activation":"1/scène — Technique déjà maintenue","texte_court":"une Technique apprise déjà maintenue coûte 1 PA de moins par round jusqu''à la fin de la scène (minimum 0). +3 aux tests pour la conserver malgré une interruption.","texte_reference":"Une fois par scène, une Technique apprise déjà maintenue devient autonome pour le reste de la scène : son entretien est réduit de 1 PA par round, minimum 0. Les tests nécessaires pour la conserver malgré une interruption bénéficient de +3.\nUne seule Technique concernée ; ni coût initial, ni autre ressource, ni concentration, ni limite du nombre de maintiens supprimés. Le bénéfice cesse si la Technique prend fin.","lore":"Une Technique déjà maintenue peut trouver pendant un instant son propre équilibre dans le Flux. L’Elyë cesse de la soutenir activement sans la laisser tomber, comme un musicien laissant résonner une note parfaitement accordée.","groupe_actuel":"Les cinq profils raciaux › Elyë — Elfes › Resonance elfique — 7 PTV","statut_regle":"correction","changements":"Accord instinctif ne demandait que Sens du Flux. Il se prend désormais au bout de la voie. Accord instinctif : la clause de non-cumul est réduite à « ne se cumule pas avec Maintien naturel »."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_whurten', 'Whurten', NULL, '{"nature":"exile","chemin":["Voies de peuple","Whurten"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_whurten_constitution_whurtenne', 'Constitution whurtenne', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Masse enracinée et Insensible à la peine se prennent désormais dans l''ordre de la voie (prérequis ajoutés). Encore debout : 1/scène → **1/scénario** (B6 validé)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-endurance-obstinee', 'Endurance obstinée', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"+3 pour résister à la fatigue, au manque de sommeil, à la marche forcée, au froid et à l''effort prolongé. Ne protège pas d''un effet surnaturel ciblé.","texte_reference":"Circonstances favorables (+3) pour resister à la fatigue, au manque de sommeil, à la marché forcee, au froid ou à l''effort prolonge lorsqu’il s''agit d''endurance corporelle. Ne protege pas d''un effet surnaturel cible.","lore":"Froid, marche forcée et privation rencontrent une physiologie faite pour durer. Le Whurten continue quand l’effort prolongé devient l’ennemi principal, tant qu’aucune puissance surnaturelle ne cherche spécifiquement à le briser.","groupe_actuel":"Les cinq profils raciaux › Whurten — Nains › Constitution whurtenne — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-masse-enracinee', 'Masse enracinée', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"SR/R","activation":"Passif","texte_court":"+3 pour résister à une projection, un renversement, un recul ou un déplacement forcé physique. Ne protège pas d''une téléportation.","texte_reference":"Circonstances favorables (+3) pour resister à une projection, un renversement, un recul ou un déplacement force reposant sur une contrainte physique. Le bonus ne s''applique pas à une téléportation ou à un effet qui déplace sans opposition physique.","lore":"Un Whurten bien campé sur ses appuis est étonnamment difficile à déplacer. Sa densité et sa posture transforment poussée, recul ou renversement en véritable lutte physique plutôt qu’en simple conséquence du choc.","groupe_actuel":"Les cinq profils raciaux › Whurten — Nains › Constitution whurtenne — 7 PTV","statut_regle":"correction","changements":"Masse enracinée et Insensible à la peine se prennent désormais dans l''ordre de la voie (prérequis ajoutés). Encore debout : 1/scène → **1/scénario** (B6 validé)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-insensible-a-la-peine', 'Insensible à la peine', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène","activation":"Actif — 1 PA — 1/scène","texte_court":"jusqu''à la fin de la scène, tu ignores les malus de dés du Stress dus aux seules blessures et à la douleur. Les PV, l''Agonie et les fonctions détruites ne changent pas. Ne se cumule pas avec Insensibilité à la douleur.","texte_reference":"Pour 1 PA, une fois par scène, ignorez jusqu’à la fin de la scène les limitations et conséquences de dés du Stress dues uniquement aux blessures et à la douleur. Les PV, l’Agonie, les fonctions détruites et le Stress d’une autre cause restent inchangés.\nL’état réel reste enregistré ; cette exception ne cumule pas une seconde amélioration des mêmes dés avec Insensibilité à la douleur.","lore":"Pendant quelques secondes, douleur et seuil de santé cessent de dicter la manière d’agir. Le Whurten ne guérit rien : il met simplement de côté la partie fonctionnelle de la souffrance jusqu’à ce que l’urgence soit passée.","groupe_actuel":"Les cinq profils raciaux › Whurten — Nains › Constitution whurtenne — 7 PTV","statut_regle":"correction","changements":"Masse enracinée et Insensible à la peine se prennent désormais dans l''ordre de la voie (prérequis ajoutés). Encore debout : 1/scène → **1/scénario** (B6 validé)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-encore-debout', 'Encore debout', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, réaction, 1/scénario","activation":"Reaction - 1/Scène","texte_court":"une source de dégâts qui te ferait passer de PV positifs à 0 PV ou moins, sans franchir ton seuil de mort, te laisse à 1 PV. Rien n''est soigné. Ne fonctionne pas si tu es déjà Agonisant.","texte_reference":"Lorsqu’une source de dégâts ferait passer le Whurten de PV positifs à 0 PV ou moins sans franchir directement son seuil de mort, il reste a 1 PV. L''effet ne soigne rien et ne fonctionne pas si le personnage était déjà Agonisant.","lore":"Le Whurten refuse parfois la chute au moment exact où les PV disent le contraire. Une fois, le corps reste debout à la limite de l’effondrement, sans effacer aucune blessure ni protéger celui qui était déjà Agonisant.","groupe_actuel":"Les cinq profils raciaux › Whurten — Nains › Constitution whurtenne — 7 PTV","statut_regle":"correction","changements":"Masse enracinée et Insensible à la peine se prennent désormais dans l''ordre de la voie (prérequis ajoutés). Encore debout : 1/scène → **1/scénario** (B6 validé)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_whurten_integrite_whurtenne', 'Intégrité whurtenne', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Ancrage whurten : fréquence 1/scène reprise du tableau (le texte l''oubliait). Âme réfractaire : fréquence « 1/effet subi » remplacée par 1/scène (simplification des fréquences, marquée). Âme réfractaire : prérequis ajouté."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-volonte-incompressible', 'Volonté incompressible', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"+3 pour résister à une domination, une possession, une contrainte mentale ou une injonction surnaturelle.","texte_reference":"Circonstances favorables (+3) pour resister à une domination, une possession, une contrainte mentale ou une injonction surnaturelle qui cherche directement a imposer un comportement contraire à la volonté du Whurten.","lore":"Domination et possession rencontrent une volonté qui accepte difficilement d’être remplacée. Quand une force surnaturelle cherche directement à imposer un comportement contraire, le Whurten oppose toute la rigidité de son identité.","groupe_actuel":"Les cinq profils raciaux › Whurten — Nains › Integrite whurtenne — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-ancrage-whurten', 'Ancrage whurten', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, réaction, 1/scène","activation":"Reaction - 1/Scène","texte_court":"après un échec non narratif à une résistance mentale ou occulte, relance le d10 et garde le second résultat.","texte_reference":"Après un échec non narratif à un test de resistance mentale ou occulte, relancez le 1d10e et conservez le second résultat.","lore":"Après avoir cédé une première fois à une pression mentale ou occulte, l’intégrité whurtenne peut reprendre le test depuis un point plus profond. Cette seconde résistance est une reconquête, pas une immunité.","groupe_actuel":"Les cinq profils raciaux › Whurten — Nains › Integrite whurtenne — 8 PTV","statut_regle":"correction","changements":"Ancrage whurten : fréquence 1/scène reprise du tableau (le texte l''oubliait). Âme réfractaire : fréquence « 1/effet subi » remplacée par 1/scène (simplification des fréquences, marquée). Âme réfractaire : prérequis ajouté."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-ame-refractaire', 'Âme réfractaire', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R, 1/scène","activation":"Nouvelle résistance — 1/effet subi","texte_court":"quand une altération surnaturelle durable touche tes souvenirs, tes convictions, ton identité ou ta forme, tu refais un test de résistance à la fin de ton prochain round, même si l''effet n''en prévoit pas. Ne répare ni des dégâts ni une transformation matérielle irréversible.","texte_reference":"Une fois par effet subi, à la fin de votre prochain round, vous obtenez une nouvelle résistance contre une altération surnaturelle durable de vos souvenirs, convictions, identité ou forme, même si l’effet n’en prévoit pas. Cette résistance ne répare pas des dégâts ni une transformation matérielle irréversible.\nIl s’agit d’un nouveau test de libération, pas d’une seconde relance du premier jet. L’effet agit normalement jusque-là ; les Marques fondamentales et Natures ne sont pas supprimées.","lore":"Une altération durable de l’identité ou de la forme rencontre chez le Whurten une inertie spirituelle croissante. Une source qui insiste sur la même transformation trouve un sujet de moins en moins facile à remodeler.","groupe_actuel":"Les cinq profils raciaux › Whurten — Nains › Integrite whurtenne — 8 PTV","statut_regle":"correction","changements":"Ancrage whurten : fréquence 1/scène reprise du tableau (le texte l''oubliait). Âme réfractaire : fréquence « 1/effet subi » remplacée par 1/scène (simplification des fréquences, marquée). Âme réfractaire : prérequis ajouté."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-inalterable', 'Inaltérable', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R, réaction, 1/scénario","activation":"Reaction - 1/Scénario","texte_court":"après un échec non narratif contre une possession, une transformation forcée ou une altération durable de ton corps ou de ton identité, l''échec devient une réussite simple (DR 0). Ne dissipe pas un effet déjà installé.","texte_reference":"Après un échec non narratif contre une possession, une transformation forcee ou une altération surnaturelle durable de l''identité ou du corps, le Whurten peut transformer cet échec en réussite simple (DR 0). Ne dissipe pas un effet déjà installe avant l''utilisation du Talent.","lore":"Dans les cas les plus graves, le Whurten peut transformer un échec récent contre possession ou transformation forcée en refus pur et simple. Ce sursaut n’arrache cependant pas un effet déjà installé avant le moment de résistance.","groupe_actuel":"Les cinq profils raciaux › Whurten — Nains › Integrite whurtenne — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_whurten_instinct_des_profondeurs', 'Instinct des profondeurs', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Mémoire des profondeurs : prérequis ajouté (ordre de la voie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-boussole-interieure', 'Boussole intérieure', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"en plus du nord, tu gardes la direction du dernier repère visité dans les labyrinthes et les bâtiments complexes. Une vraie distorsion spatiale reste une limite.","texte_reference":"Le Sens magnétique inné donne toujours le nord ; Boussole intérieure conserve en plus la direction du dernier repère visité dans les labyrinthes et bâtiments complexes. Les vraies distorsions spatiales restent une limite.","lore":"Sous terre, le Whurten garde un axe mental stable même lorsque tous les repères visuels se ressemblent. Nord magnétique et dernier point certain restent présents comme deux lignes intérieurement impossibles à confondre.","groupe_actuel":"Les cinq profils raciaux › Whurten — Nains › Instinct des profondeurs — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-lecture-du-champ', 'Lecture du champ', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, 1 PA","activation":"Actif — 1 PA — 20 m","texte_court":"Esprit + Perception repère grossièrement, à 20 m, les masses ferromagnétiques et les fortes perturbations magnétiques. Le DR affine la direction et l''intensité.","texte_reference":"Pour 1 PA, un test d’Esprit + Perception repère grossièrement à 20 m les masses ferromagnétiques et perturbations magnétiques importantes transmises jusqu’à vous. Le DR affine direction et intensité, sans carte précise ni détection universelle de tous les appareils.","lore":"Les masses ferromagnétiques et machines puissantes déforment le champ que le Whurten ressent. À travers la roche ou les cloisons ordinaires, ces perturbations deviennent des directions approximatives vers ce qui se cache.","groupe_actuel":"Les cinq profils raciaux › Whurten — Nains › Instinct des profondeurs — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-memoire-des-profondeurs', 'Mémoire des profondeurs', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Passif","texte_court":"un itinéraire que tu as parcouru dans un réseau souterrain ou un bâtiment, tu le retraces sans jet tant que l''architecture n''a pas été profondément modifiée. Tu remarques aussitôt qu''un passage connu a été déplacé ou condamné.","texte_reference":"Un itineraire que le Whurten’a lui-même parcouru dans un réseau souterrain ou structurel peut être retrace sans jet tant que son’architecture générale n''a pas été profondément modifiée. Il reconnaît également rapidement qu''un passage connu a été déplace, condamne ou transforme.","lore":"Un chemin souterrain parcouru une fois s’inscrit comme une structure plutôt qu’une suite de virages. Le Whurten peut le refaire plus tard et remarque vite lorsqu’un passage connu a été condamné, déplacé ou transformé.","groupe_actuel":"Les cinq profils raciaux › Whurten — Nains › Instinct des profondeurs — 7 PTV","statut_regle":"correction","changements":"Mémoire des profondeurs : prérequis ajouté (ordre de la voie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-point-fixe', 'Point fixe', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"c","acces":"V/SR/R","activation":"Choix du repère sur place — durée : scénario","texte_court":"choisis sur place jusqu''à trois repères, notés sur ta fiche. Jusqu''à la fin du scénario, tu connais leur direction et leur distance approximative malgré les illusions d''orientation. Une vraie discontinuité spatiale peut rompre le lien.","texte_reference":"Conservez jusqu’à trois repères physiquement visités jusqu’à la fin du scénario, avec direction et distance approximatives malgré les illusions d’orientation. Une vraie discontinuité spatiale peut rompre le repérage ; choisir un repère exige d’être sur place.\nNe révèle aucun itinéraire non parcouru et ne dissipe pas les illusions. Les repères doivent être nommés et conservés sur la fiche.","lore":"Une fois un point physiquement atteint, le Whurten peut l’emporter comme référence interne. Distance et direction restent estimables malgré obscurité, labyrinthe ou illusions d’orientation, tant que l’espace lui-même n’a pas réellement été disloqué.","groupe_actuel":"Les cinq profils raciaux › Whurten — Nains › Instinct des profondeurs — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_ashyll', 'Ashyll', NULL, '{"nature":"exile","chemin":["Voies de peuple","Ashyll"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_ashyll_genie_ashyll', 'Génie ashyll', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Rien ne se perd : le stock de trois lots à noter sur la fiche devient une récupération 1/scène (simplification, marquée). Ça devrait marcher et Rien ne se perd se prennent dans l''ordre de la voie. Impossible ? Non. Mal préparé. : la comparaison de designer avec Bricolage est retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-diagnostic-sauvage', 'Diagnostic sauvage', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, 1 PA","activation":"Examen — 1 PA","texte_court":"tu identifies le sous-système défaillant accessible à l''observation. +3 au diagnostic ou à la première réparation qui l''exploite.","texte_reference":"Après 1 PA d’examen, identifiez le sous-système défaillant accessible à l’observation et bénéficiez de +3 au test de diagnostic ou à la première réparation qui l’exploite. Une cause réellement cachée demande toujours les examens adaptés.","lore":"Le diagnostic ashyll commence par ouvrir, écouter et regarder ce qui ne se comporte plus comme prévu. La cause matérielle principale ou le sous-système fautif devient évident sans que la réparation se fournisse automatiquement avec le constat.","groupe_actuel":"Les cinq profils raciaux › Ashyll — Gobelins › Genie ashyll — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-ca-devrait-marcher', 'Ça devrait marcher', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"V/SR/R, 1/scène","activation":"1/scène","texte_court":"une tâche technique simple faite avec un outil détourné crédible gagne +3 et ignore jusqu''à −3 dus au matériel improvisé. Aucun composant indispensable ni énergie n''est inventé.","texte_reference":"Une fois par scène, une tâche technique simple utilisant un outil détourné mais crédible bénéficie de +3, en plus de l’annulation de jusqu’à −3 dus à ce matériel improvisé. Aucun composant indispensable ni source d’énergie n’est inventé.\nLes bonus circonstanciels favorables équivalents ne s’ajoutent pas. Il faut un véritable usage détourné, pas déclarer son outil habituel « improvisé ».","lore":"Un outil n’a pas besoin d’être celui du manuel s’il remplit vraiment la même fonction. L’Ashyll ignore la maladresse de l’improvisation lorsque la substitution est plausible et qu’aucune pièce indispensable ne manque.","groupe_actuel":"Les cinq profils raciaux › Ashyll — Gobelins › Genie ashyll — 8 PTV","statut_regle":"correction","changements":"Rien ne se perd : le stock de trois lots à noter sur la fiche devient une récupération 1/scène (simplification, marquée). Ça devrait marcher et Rien ne se perd se prennent dans l''ordre de la voie. Impossible ? Non. Mal préparé. : la comparaison de designer avec Bricolage est retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-rien-ne-se-perd', 'Rien ne se perd', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"c","acces":"V/SR/R, 1/scène","activation":"Récupération réelle — 3 lots maximum","texte_court":"dans une épave ou un appareil réellement accessible, tu récupères le composant ordinaire qui manquait à un bricolage. Il n''a jamais de pièce rare ni de valeur de revente.","texte_reference":"Après récupération dans des appareils ou épaves réellement accessibles, conservez jusqu’à trois lots de composants ordinaires destinés à vos bricolages. Chaque lot est consommé lorsqu’il remplace des fournitures plausibles ; aucune pièce rare ni valeur de revente n’est créée.\nIl s’agit d’un stock de ressources identifié, pas de trois objets au choix tirés du néant.","lore":"Une épave est un magasin qui n’a pas encore été trié. L’Ashyll récupère le composant mundane le plus utile pour un prochain bricolage et le garde comme réserve, sans transformer cette trouvaille en pièce rare ou marchandise précieuse.","groupe_actuel":"Les cinq profils raciaux › Ashyll — Gobelins › Genie ashyll — 8 PTV","statut_regle":"correction","changements":"Rien ne se perd : le stock de trois lots à noter sur la fiche devient une récupération 1/scène (simplification, marquée). Ça devrait marcher et Rien ne se perd se prennent dans l''ordre de la voie. Impossible ? Non. Mal préparé. : la comparaison de designer avec Bricolage est retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-bricolage-de-fortune', 'Bricolage de fortune', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, 2 PA sous pression","activation":"Actif — 2 PA sous pression","texte_court":"avec des outils et des matériaux plausibles, tu remets une fonction de base en service jusqu''à la fin de la scène. Le test technique reste dû.","texte_reference":"Avec outils et matériaux plausibles, remettez une fonction de base en service en 2 PA sous pression, jusqu’à la fin de la scène. Le test technique nécessaire reste dû ; ni appareil détruit ni fonction nouvelle ne sont recréés.","lore":"Le Génie ashyll ne cherche pas à rendre l’objet beau, seulement à lui rendre une fonction pour maintenant. Matériaux locaux et adaptation rapide produisent un montage utile jusqu’à la fin de la scène, souvent trop grossier pour durer davantage.","groupe_actuel":"Les cinq profils raciaux › Ashyll — Gobelins › Genie ashyll — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-impossible-non-mal-prepare', 'Impossible ? Non. Mal préparé.', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R, 1 PA, 1/scénario","activation":"Actif — 1 PA — 1/scénario","texte_court":"tu reconfigures un appareil réel vers une fonction nouvelle mais plausible, avec +3 au test. La fonction tient la scène. Ni attaque gratuite ni technologie inconnue.","texte_reference":"Une fois par scénario, reconfigurez en 1 PA un appareil réel vers une fonction nouvelle mais techniquement plausible, avec +3 au test nécessaire. Cette invention fonctionne pour la scène ; connaissances, matériaux et énergie restent requis.\nBricolage de fortune rétablit une fonction existante ; ce sommet invente une nouvelle utilisation à une vitesse exceptionnelle. Aucune attaque, énergie ou fabrication de technologie inconnue gratuite.","lore":"L’Ashyll entend souvent « impossible » là où il voit seulement un atelier incomplet. Si l’outil ou le composant manquant n’est pas fondamental, il improvise l’équivalent local et poursuit une construction techniquement réalisable.","groupe_actuel":"Les cinq profils raciaux › Ashyll — Gobelins › Genie ashyll — 8 PTV","statut_regle":"correction","changements":"Rien ne se perd : le stock de trois lots à noter sur la fiche devient une récupération 1/scène (simplification, marquée). Ça devrait marcher et Rien ne se perd se prennent dans l''ordre de la voie. Impossible ? Non. Mal préparé. : la comparaison de designer avec Bricolage est retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_ashyll_instinct_du_terrier', 'Instinct du terrier', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Passage de rat : fréquence 1/scène reprise du tableau. Oreille du terrier : prérequis ajouté (ordre de la voie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-faufiler', 'Faufiler', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"tu te déplaces sans pénalité dans les conduits, les vides techniques, sous les meubles et dans les passages de maintenance à ta taille.","texte_reference":"L''Ashyll se déplace normalement dans les conduits, vides techniques, dessous de mobilier, passages de maintenance et espaces comparables compatibles avec sa morphologie, sans subir de penalite de vitesse due au seul manque de place.","lore":"La petite morphologie ashyll considère conduits, dessous de mobilier et vides techniques comme des voies normales. Là où un humain ramperait péniblement, le Gobelin se déplace sans perdre son rythme à cause du seul manque d’espace.","groupe_actuel":"Les cinq profils raciaux › Ashyll — Gobelins › Instinct du terrier — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-oreille-du-terrier', 'Oreille du terrier', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"V/SR/R, 1 PA","activation":"Actif — 1 PA — 10 m","texte_court":"l''oreille contre une paroi conductrice, Esprit + Perception localise une activité sonore ou mécanique à 10 m au plus. L''Ouïe ashyll ne s''applique qu''une fois.","texte_reference":"Pour 1 PA, en contact avec une paroi conductrice, localisez approximativement une activité sonore ou mécanique transmise à 10 m maximum grâce à Esprit + Perception. Le bonus d’Ouïe ashyll s’applique une seule fois si pertinent ; une isolation réelle reste efficace.","lore":"Une paroi transmet plus de vie qu’elle n’en montre. L’Ashyll colle l’oreille au matériau et lit bruits, vibrations et mouvements mécaniques pour situer grossièrement ce qui travaille ou se déplace de l’autre côté.","groupe_actuel":"Les cinq profils raciaux › Ashyll — Gobelins › Instinct du terrier — 7 PTV","statut_regle":"correction","changements":"Passage de rat : fréquence 1/scène reprise du tableau. Oreille du terrier : prérequis ajouté (ordre de la voie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-passage-de-rat', 'Passage de rat', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, 1/scène","activation":"1/Scène","texte_court":"face à un obstacle ordinaire non hermétique, le MJ t''indique un passage physique plausible (gaine, trappe, conduit), s''il en existe un.","texte_reference":"Face à un obstacle ordinaire non hermétique dans un’environnement construit, le MJ indique un passage physique plausible que l''Ashyll peut emprunter ou atteindre - gaine, trappe, espace de maintenance, conduit ou équivalent - s''il en existe un. Le Talent ne crée pas de passage dans une structure réellement scellée.","lore":"Dans un bâtiment qui n’est pas vraiment hermétique, l’Ashyll repère les passages oubliés par ceux qui pensent à hauteur humaine : gaine, trappe, vide de maintenance ou conduit assez grand pour sa morphologie.","groupe_actuel":"Les cinq profils raciaux › Ashyll — Gobelins › Instinct du terrier — 7 PTV","statut_regle":"correction","changements":"Passage de rat : fréquence 1/scène reprise du tableau. Oreille du terrier : prérequis ajouté (ordre de la voie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-toujours-une-sortie', 'Toujours une sortie', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R, 1/scène","activation":"1/scène","texte_court":"le MJ t''indique une route de sortie viable du bâtiment ou du réseau urbain, s''il en reste une. Elle peut être surveillée et doit être parcourue.","texte_reference":"Une fois par scène, le MJ indique une route de sortie physiquement viable dans le bâtiment ou réseau urbain exploré, s’il en existe encore une. Elle peut rester surveillée ou dangereuse et doit être réellement parcourue.\nNe garantit pas la réussite d’une fuite ; ne crée ni passage ni téléportation.","lore":"Les cinq profils raciaux a survécu à Aèr, à l’exil ou aux siècles terrestres parce que ses membres ont continué à transmettre des pratiques concrètes. Ce Talent transforme l’expérience accumulée par Instinct du terrier — 7 PTV en méthode fiable. Il ne donne pas l’omniscience : il rend accessible un type précis de connaissance que le personnage a appris à chercher, conserver ou interpréter.","groupe_actuel":"Les cinq profils raciaux › Ashyll — Gobelins › Instinct du terrier — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_ashyll_culot_ashyll', 'Culot ashyll', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Rebondir : fréquence 1/scène reprise du tableau. Faire avec ce qu''on a : le prérequis Ça devrait marcher, pris dans une autre voie, est retiré. L''ordre de la voie suffit."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-meme-pas-peur', 'Même pas peur', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"+3 pour résister à l''intimidation et à la peur dues à la taille, au statut, à la réputation ou à la menace directe d''un adversaire. Pas contre une terreur purement surnaturelle.","texte_reference":"Circonstances favorables (+3) pour resister à l''intimidation et à la peur provoquées principalement par la taille, le statut, la réputation ou la menace directe d''un’adversaire. Ne protege pas contre une terreur surnaturelle sans composante psychologique ordinaire.","lore":"Le Culot ashyll refuse de confondre taille, réputation et destin. Une menace impressionnante reste une menace, mais elle a plus de mal à obtenir une soumission automatique simplement parce qu’elle paraît plus grande ou plus prestigieuse.","groupe_actuel":"Les cinq profils raciaux › Ashyll — Gobelins › Culot ashyll — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-rebondir', 'Rebondir', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, 1/scène","activation":"1/Scène","texte_court":"après un échec non narratif, tu tentes aussitôt une approche vraiment différente, avec une autre Compétence. Pas de PA supplémentaire si les deux approches s''enchaînent naturellement.","texte_reference":"Après un échec non narratif, l''Ashyll peut immédiatement tenter une approche réellement differente du même probleme avec une autre Compétence, sans payer un PA supplémentaire si les deux approches s''enchainent naturellement. Ce n''est jamais une seconde tentative identique.","lore":"Après un échec, l’Ashyll change vraiment d’angle au lieu de répéter le même geste. Une autre compétence ou approche prend le relais immédiatement lorsque les deux solutions s’enchaînent naturellement dans la fiction.","groupe_actuel":"Les cinq profils raciaux › Ashyll — Gobelins › Culot ashyll — 8 PTV","statut_regle":"correction","changements":"Rebondir : fréquence 1/scène reprise du tableau. Faire avec ce qu''on a : le prérequis Ça devrait marcher, pris dans une autre voie, est retiré. L''ordre de la voie suffit."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-profiter-du-flottement', 'Profiter du flottement', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R, réaction gratuite, 1/round","activation":"Réaction gratuite — 1/round","texte_court":"quand un adversaire échoue à te surveiller ou à te contenir, tu tentes gratuitement de te dissimuler ou de te dégager de la prise. Aucune attaque gratuite.","texte_reference":"Une fois par round, après un échec adverse à vous surveiller ou contenir, tentez gratuitement de vous dissimuler ou de vous dégager d’une prise dont l’échec a créé l’ouverture. Le test et les possibilités physiques restent nécessaires ; aucune attaque gratuite.","lore":"L’Ashyll vit dans les secondes où les autres ratent leur propre plan. Une garde qui échoue, une prise qui lâche ou une erreur narrative crée immédiatement un petit déplacement ou une manipulation avant que quelqu’un ait refermé l’ouverture.","groupe_actuel":"Les cinq profils raciaux › Ashyll — Gobelins › Culot ashyll — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-faire-avec-ce-qu-on-a', 'Faire avec ce qu''on a', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R, 1/scène","activation":"1/scène","texte_court":"quand une ressource ordinaire manque à un plan, le MJ désigne un substitut local. Jusqu''à trois participants gagnent +3 à leur premier test qui met en œuvre le plan de remplacement.","texte_reference":"Une fois par scène, le MJ désigne un substitut local réellement exploitable lorsqu’une ressource ordinaire manque à un plan. Jusqu’à trois participants bénéficient chacun de +3 à leur premier test mettant en œuvre ce plan de remplacement et en acceptent les compromis.\nPas de fabrication de ressource. Le plan de remplacement est fixé avant les jets et les bonus équivalents ne s’empilent pas.","lore":"L’Ashyll cherche d’abord autour de lui avant de déclarer qu’il manque quelque chose. Si un substitut plausible existe réellement dans la scène, son esprit l’identifie et accepte immédiatement le compromis qu’il implique.","groupe_actuel":"Les cinq profils raciaux › Ashyll — Gobelins › Culot ashyll — 8 PTV","statut_regle":"correction","changements":"Rebondir : fréquence 1/scène reprise du tableau. Faire avec ce qu''on a : le prérequis Ça devrait marcher, pris dans une autre voie, est retiré. L''ordre de la voie suffit."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_thulkar', 'Thulkar', NULL, '{"nature":"exile","chemin":["Voies de peuple","Thulkar"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_thulkar_puissance_thulkar', 'Puissance thulkar', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte (courte)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Mains de guerre se prend après Poigne thulkar (ordre de la voie). Accès R seulement : inchangé (voir la question 3)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-poigne-thulkar', 'Poigne thulkar', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":"Passif","texte_court":"+3 pour résister à un désarmement ou pour garder une saisie. Tu tiens d''une main ce qu''un humain tient à deux.","texte_reference":"Circonstances favorables (+3) pour resister à un désarmement ou maintenir une saisie physique déjà obtenue. Le Thulkar peut également maintenir d''une main un objet ou un individu que sa Vigueur lui permet raisonnablement de tenir, même si un humain’aurait normalement besoin des deux mains.","lore":"Une prise thulkar se referme avec assez de force pour que l’objet ou l’adversaire devienne difficile à arracher. Ce qui tient dans sa main y reste jusqu’à ce qu’une force réelle parvienne à vaincre la poigne.","groupe_actuel":"Les cinq profils raciaux › Thulkar — Orques › Puissance thulkar — 4 PTV","statut_regle":"correction","changements":"Mains de guerre se prend après Poigne thulkar (ordre de la voie). Accès R seulement : inchangé (voir la question 3)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-mains-de-guerre', 'Mains de guerre', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"R","activation":"Passif","texte_court":"tes attaques de Pugilat font DGT 3 au lieu de DGT 1.","texte_reference":"Les attaques de Pugilat du Thulkar utilisent DGT 3 au lieu du DGT 1 normal.","lore":"Les mains thulkar ne sont pas des armes improvisées mais des outils de guerre naturels. Masse osseuse, muscles et habitude du contact font de chaque coup une attaque bien plus lourde que le pugilat humain ordinaire.","groupe_actuel":"Les cinq profils raciaux › Thulkar — Orques › Puissance thulkar — 4 PTV","statut_regle":"correction","changements":"Mains de guerre se prend après Poigne thulkar (ordre de la voie). Accès R seulement : inchangé (voir la question 3)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-force-de-rupture', 'Force de rupture', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":"Passif","texte_court":"quand tu attaques un objet, une porte, une cloison, un verrou ou un véhicule immobilisé, tu ignores 2 points de Protection matérielle. Pas contre une armure portée.","texte_reference":"Lorsqu’il’attaque volontairement un objet, une porte, une cloison, un verrou, un vehicule immobilise ou une autre structure matérielle, le Thulkar ignore 2 points de Protection matérielle. Ne s''applique pas à l''armure portée par une creature pendant une attaque normale.","lore":"Une porte ou une structure n’est pas protégée comme un corps qui se défend. Le Thulkar frappe là pour rompre la matière elle-même, exploitant toute sa puissance contre les points où la protection matérielle peut réellement céder.","groupe_actuel":"Les cinq profils raciaux › Thulkar — Orques › Puissance thulkar — 4 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_thulkar_corps_thulkar', 'Corps thulkar', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Douleur familière : prérequis ajouté (ordre de la voie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-peau-epaisse', 'Peau épaisse', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":"Passif","texte_court":"Armure corporelle 1, qui se cumule avec l''armure portée.","texte_reference":"Armure corporelle 1. Elle se cumule avec une armure portée selon les règles normales Armure corporelle + Armure portée.","lore":"La peau thulkar est déjà une protection avant toute pièce d’équipement. Épaisseur, tissu conjonctif et densité forment une armure naturelle qui complète normalement ce que le guerrier porte par-dessus.","groupe_actuel":"Les cinq profils raciaux › Thulkar — Orques › Corps thulkar — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-douleur-familiere', 'Douleur familière', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"SR/R","activation":"Passif","texte_court":"+3 pour résister à un test provoqué par la douleur, une blessure ou une menace de souffrance.","texte_reference":"Circonstances favorables (+3) pour resister à un test provoqué directement par la douleur physique, une blessure ou une menace de souffrance. Ne protege pas contre la peur qui ne repose pas sur la douleur.","lore":"Le corps thulkar connaît la douleur comme une compagne ancienne plutôt qu’un signal inconnu. Blessure ou menace de souffrance ont plus de mal à lui imposer panique et rupture lorsqu’elles reposent seulement sur ce registre physique.","groupe_actuel":"Les cinq profils raciaux › Thulkar — Orques › Corps thulkar — 7 PTV","statut_regle":"correction","changements":"Douleur familière : prérequis ajouté (ordre de la voie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-encaisser', 'Encaisser', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, réaction gratuite, 1/scène","activation":"Réaction gratuite — 1/scène","texte_court":"réduis de 5 les dégâts d''une attaque physique, après Armure et Protection (minimum 0).","texte_reference":"Une fois par scène, réduisez sans PA supplémentaire de 5 les dégâts d’une attaque physique après Armure et Protection, minimum 0. Un effet ignorant explicitement toute résistance physique reste exclu.","lore":"Le Thulkar sait prendre le choc avec ce que son corps possède de plus dense. Après armure et protection, il contracte, tourne ou absorbe assez pour retrancher encore une part de la violence purement matérielle.","groupe_actuel":"Les cinq profils raciaux › Thulkar — Orques › Corps thulkar — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-toujours-dangereux', 'Toujours dangereux', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Passif","texte_court":"quand tu es Agonisant, tu peux utiliser ton unique PA pour une attaque de Mêlée ou de Pugilat, ou pour une Défense active.","texte_reference":"Lorsqu’il est Agonisant, le Thulkar peut utiliser son unique PA du round pour effectuer une attaque de Melee ou de Pugilat, ou une Défense active, en plus des actions normalement permises a cet état. Il reste Agonisant et toute autre limitation s''applique.","lore":"Même Agonisant, un Thulkar reste capable d’un dernier geste violent. Son unique instant d’action peut encore devenir frappe ou défense plutôt que simple survie passive.","groupe_actuel":"Les cinq profils raciaux › Thulkar — Orques › Corps thulkar — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_thulkar_presence_thulkar', 'Présence thulkar', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte (courte)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Monter au défi et Ne pas détourner le regard prennent rang après Masse imposante."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-masse-imposante', 'Masse imposante', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":"Passif","texte_court":"quand ta vraie morphologie est visible et fait la menace, tu utilises Vigueur au lieu de Charisme pour Intimider.","texte_reference":"Lorsque sa véritable morphologie est visible et constitue réellement le coeur de la menace, le Thulkar peut utiliser Vigueur à la place de Charisme pour un test d''Intimidation. Cela ne change pas la Compétence utilisee.","lore":"Quand sa vraie morphologie est visible, le Thulkar peut intimider par la simple évidence de sa force. Le corps devient l’argument principal, remplaçant l’aisance sociale par une présence physique impossible à ignorer.","groupe_actuel":"Les cinq profils raciaux › Thulkar — Orques › Presence thulkar — 5 PTV","statut_regle":"correction","changements":"Monter au défi et Ne pas détourner le regard prennent rang après Masse imposante."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-monter-au-defi', 'Monter au défi', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1/scène","activation":"Défi accepté — 1/scène","texte_court":"après avoir accepté ouvertement un vrai défi, +3 aux actions qui y répondent jusqu''à la fin de la scène. Un seul défi actif.","texte_reference":"Après acceptation ouverte d’un véritable défi adverse, bénéficiez de +3 aux actions qui y répondent directement pendant la scène. Un seul défi actif ; provocations fabriquées par vos alliés et actions sans rapport sont exclues.","lore":"Un défi explicite réveille quelque chose de profondément thulkar. L’accepter publiquement donne à la première réponse directe une netteté et une détermination que la simple provocation vague ne suffit pas à produire.","groupe_actuel":"Les cinq profils raciaux › Thulkar — Orques › Presence thulkar — 5 PTV","statut_regle":"correction","changements":"Monter au défi et Ne pas détourner le regard prennent rang après Masse imposante."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-ne-pas-detourner-le-regard', 'Ne pas détourner le regard', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"SR/R, 1/scène","activation":"Après résistance réussie — 1/scène","texte_court":"après avoir résisté à l''intimidation directe d''un adversaire, la répétition de la même intimidation ordinaire ne peut plus te faire reculer ni céder de la scène.","texte_reference":"Une fois par scène, après une résistance réussie à l’intimidation directe d’un adversaire, ses répétitions de la même intimidation ordinaire ne peuvent plus vous faire reculer ou céder pendant la scène. Une menace réellement différente et une emprise surnaturelle restent opposables.","lore":"Le Thulkar peut opposer une volonté frontale à celui qui cherche à le faire plier. S’il tient, l’adversaire perd l’avantage social qu’il espérait tirer de cette intimidation directe.","groupe_actuel":"Les cinq profils raciaux › Thulkar — Orques › Presence thulkar — 5 PTV","statut_regle":"correction","changements":"Monter au défi et Ne pas détourner le regard prennent rang après Masse imposante."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_azmenorien', 'Azménorien', NULL, '{"nature":"exile","chemin":["Voies de peuple","Azménorien"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_azmenorien_jusqu_au_bout', 'Jusqu''au bout', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Pousser la limite : formule de journal des modifications retirée (« n''interdit plus les aides »). Hyperfocalisation : fréquence 1/scène reprise du tableau. Jusqu''à la rupture : clause « Aura » retirée, déjà couverte par « irréductibles »."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-insister', 'Insister', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, 1/scène","activation":"Nouvelle tentative payante — 1/scène","texte_court":"tu retentes une action matériellement répétable malgré la règle de non-répétition, à la même difficulté, en repayant son temps et ses PA. Rien d''irréversible n''est annulé.","texte_reference":"Une fois par scène, retentez une action matériellement répétable malgré la règle de non-spam, à la même difficulté. Vous payez à nouveau son temps et ses PA ; aucun échec narratif ou événement irréversible n’est annulé.","lore":"Un premier échec ne suffit pas toujours à lui faire lâcher l’affaire. L’Azménorien tente de nouveau exactement parce qu’il refuse la règle tacite qui voudrait attendre un changement de situation, mais cette obstination rend l’essai plus difficile.","groupe_actuel":"Les cinq profils raciaux › Azménorien › Jusqu au bout — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-pousser-la-limite', 'Pousser la limite', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, 1/scène","activation":"1/scène","texte_court":"+3 à un test où tu pousses réellement tes capacités. Ne se cumule pas avec une circonstance favorable équivalente.","texte_reference":"Une fois par scène, obtenez +3 sur un test en poussant réellement vos capacités. Ce bonus ne se cumule pas avec une circonstance favorable équivalente, mais n’interdit plus les aides sur les étapes ultérieures de la tâche.","lore":"Avant l’action, l’Azménorien décide de dépasser son régime raisonnable. Tout ce qui peut être donné maintenant est donné, ce qui améliore nettement la tentative mais épuise la possibilité de recommencer la même poussée sur cette action prolongée.","groupe_actuel":"Les cinq profils raciaux › Azménorien › Jusqu au bout — 8 PTV","statut_regle":"correction","changements":"Pousser la limite : formule de journal des modifications retirée (« n''interdit plus les aides »). Hyperfocalisation : fréquence 1/scène reprise du tableau. Jusqu''à la rupture : clause « Aura » retirée, déjà couverte par « irréductibles »."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-hyperfocalisation', 'Hyperfocalisation', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R, 1/scène","activation":"1/Scène","texte_court":"sur une tâche précise, jusqu''à sa fin, tu ignores jusqu''à −3 dus au bruit, à la distraction, à l''inconfort ou à la pression. Pendant ce temps, tu ne peux assister personne.","texte_reference":"Choisissez une tâche précise. jusqu''à sa résolution ou jusqu''à ce que l''Azménorien l''abandonne, ignorez jusqu''à -3 de malus provenant uniquement du bruit, de la distraction, de l''inconfort ou de la pression’ambiante. Il ne peut pas simultanement fournir une Assistance reposant sur son’attention à une autre tâche.","lore":"Jusqu’au-bout signifie parfois fermer tout le reste. Bruit, inconfort et pression périphérique cessent de distraire l’Azménorien tant qu’il poursuit une tâche précise, au prix d’une attention devenue indisponible pour aider ailleurs.","groupe_actuel":"Les cinq profils raciaux › Azménorien › Jusqu au bout — 8 PTV","statut_regle":"correction","changements":"Pousser la limite : formule de journal des modifications retirée (« n''interdit plus les aides »). Hyperfocalisation : fréquence 1/scène reprise du tableau. Jusqu''à la rupture : clause « Aura » retirée, déjà couverte par « irréductibles »."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-jusqu-a-la-rupture', 'Jusqu''à la rupture', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R, 1/scénario","activation":"1/scénario","texte_court":"un test décisif gagne +3. S''il échoue sans échec narratif, tu peux subir 3 dégâts irréductibles pour le relancer, et tu gardes le second résultat.","texte_reference":"Une fois par scénario, un test décisif bénéficie de +3 ; s’il échoue sans échec narratif, vous pouvez subir 3 dégâts irréductibles pour le relancer. Le second résultat est conservé et les dégâts ne sont payés que si vous utilisez cette relance.\nLes dégâts ne doivent pas être convertis en simple perte d’Aura ou ignorés par un bonus de douleur ; pas de seconde relance de Talent.","lore":"Dans les moments décisifs, certains Azménoriens préfèrent casser leur propre corps plutôt que céder. La performance gagne à la fois puissance et seconde chance, tandis que la douleur arrive ensuite que le geste ait réussi ou non.","groupe_actuel":"Les cinq profils raciaux › Azménorien › Jusqu au bout — 8 PTV","statut_regle":"correction","changements":"Pousser la limite : formule de journal des modifications retirée (« n''interdit plus les aides »). Hyperfocalisation : fréquence 1/scène reprise du tableau. Jusqu''à la rupture : clause « Aura » retirée, déjà couverte par « irréductibles »."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_azmenorien_don_d_azmenor', 'Don d''Azménor', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Correction instinctive : fréquence 1/scène reprise du tableau. Maintien naturel : prérequis ajouté (ordre de la voie). Incantation fulgurante : inchangée (voir la question 2)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-canalisation-naturelle', 'Canalisation naturelle', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Passif","texte_court":"ton corps sert de focus ordinaire pour une Technique apprise. Il ne remplace jamais un composant unique, un symbole rituel précis ou un réactif consommé.","texte_reference":"Le propre corps de l''Azménorien compte comme un focus ou conduit générique suffisant pour une Technique magique apprise qui n''exige qu''un support de canalisation ordinaire. Le Talent ne remplace jamais un composant unique, un symbole rituel precis ou un reactif explicitement consomme.","lore":"Le corps azménorien sait servir de conduit là où une Technique n’exige qu’un focus ordinaire. Sa propre nature suffit à faire passer la magie, mais jamais à remplacer le symbole ou réactif unique qui fait partie du rite lui-même.","groupe_actuel":"Les cinq profils raciaux › Azménorien › Don d''Azmenor — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-correction-instinctive', 'Correction instinctive', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1/scène","activation":"Reaction - 1/Scène","texte_court":"après un échec non narratif à l''activation d''une Technique apprise, relance le d10 et garde le second résultat.","texte_reference":"Après un échec non narratif au jet d''activation d''une Technique magique apprise, relancez le 1d10e et conservez le second résultat.","lore":"Lorsqu’une activation magique déraille sans catastrophe, l’Azménorien sent immédiatement où son geste ou sa volonté s’est désaccordé. Il corrige une fois l’incantation et reprend la tentative avec le même savoir appris.","groupe_actuel":"Les cinq profils raciaux › Azménorien › Don d''Azmenor — 8 PTV","statut_regle":"correction","changements":"Correction instinctive : fréquence 1/scène reprise du tableau. Maintien naturel : prérequis ajouté (ordre de la voie). Incantation fulgurante : inchangée (voir la question 2)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-maintien-naturel', 'Maintien naturel', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"SR/R, 1/scène","activation":"1/scène — 3 rounds","texte_court":"pendant trois rounds, une Technique maintenue coûte 1 PA de moins par round (minimum 0). Ne se cumule pas avec Accord instinctif.","texte_reference":"Une fois par scène, réduisez de 1 PA par round le maintien d’une Technique apprise pendant trois rounds consécutifs, minimum 0. Sa concentration, ses ressources et les autres maintiens restent normaux.\nLe bénéfice cesse avec la Technique ; ne se cumule pas avec Accord instinctif sur le même entretien.","lore":"Une Technique déjà ouverte peut rester portée par le Flux pendant un round sans réclamer son entretien habituel. L’Azménorien choisit laquelle il laisse ainsi respirer naturellement lorsque plusieurs pouvoirs sont actifs.","groupe_actuel":"Les cinq profils raciaux › Azménorien › Don d''Azmenor — 8 PTV","statut_regle":"correction","changements":"Correction instinctive : fréquence 1/scène reprise du tableau. Maintien naturel : prérequis ajouté (ordre de la voie). Incantation fulgurante : inchangée (voir la question 2)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-incantation-fulgurante', 'Incantation fulgurante', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1/round","activation":"1/round — réduction de 1 PA","texte_court":"réduis de 1 PA l''activation d''une Technique apprise (minimum 1 PA). Une incantation longue n''en profite qu''une fois.","texte_reference":"Une fois par round, réduisez de 1 PA le coût d’activation d’une Technique apprise, minimum 1 PA. Une même incantation longue ne peut recevoir cette réduction qu’une fois et les ressources autres que les PA restent dues.","lore":"La magie vient si naturellement que certaines étapes cessent d’exiger toute l’attention qu’elles coûteraient à un praticien moins intuitif. L’Azménorien resserre l’activation sans pouvoir réduire un véritable rituel à un geste instantané.","groupe_actuel":"Les cinq profils raciaux › Azménorien › Don d''Azmenor — 8 PTV","statut_regle":"correction","changements":"Correction instinctive : fréquence 1/scène reprise du tableau. Maintien naturel : prérequis ajouté (ordre de la voie). Incantation fulgurante : inchangée (voir la question 2)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_silcenters', 'Silcenters', NULL, '{"nature":"exile","chemin":["Traditions de Vérité","Silcenters"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_traditions_de_verite', 'Traditions de Vérité', NULL, '{"nature":"exile","chemin":["Traditions de Vérité"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_silcenters_protocoles_de_continuite', 'Protocoles de Continuité', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Les quatre talents existent sous les mêmes noms chez les Extrals : doublon admis (A4), textes d''origine gardés. *Retiré le 30/10* : la restriction « un cran à la fois » que j''avais ajoutée pour les distinguer. Coordination de Silcenter : elle passe par les codes du Silcenter, à la voix ou aux signes. Révélation drillée et Repli réflexe : fréquence 1/scène reprise du tableau."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-revelation-drillee', 'Révélation drillée', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, 1/scène","activation":"1/Scène","texte_court":"pendant ton tour, tu fais une transition personnelle (V→SR, SR→R ou V→R) sans payer le PA. Ne force pas une Révélation bloquée.","texte_reference":"Au cours de son tour, effectuez une transition personnelle V vers SR, SR vers R ou V vers R sans payer le PA normalement requis. Le Talent ne contourne pas une Révélation rendue impossible ou activement bloquee.","lore":"La transition V/SR/R a été répétée assez souvent pour devenir un geste intégré au tour. Le personnage ouvre ou referme sa Révélation sans y perdre le temps normalement nécessaire tant qu’aucun blocage extérieur ne s’y oppose.","groupe_actuel":"Silcenters et HDS › Protocoles de Continuité — 7 PTV","statut_regle":"correction","changements":"Les quatre talents existent sous les mêmes noms chez les Extrals : doublon admis (A4), textes d''origine gardés. *Retiré le 30/10* : la restriction « un cran à la fois » que j''avais ajoutée pour les distinguer. Coordination de Silcenter : elle passe par les codes du Silcenter, à la voix ou aux signes. Révélation drillée et Repli réflexe : fréquence 1/scène reprise du tableau."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-repli-reflexe', 'Repli réflexe', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"SR/R, réaction, 1/scène","activation":"Reaction - 1/Scène","texte_court":"quand un témoin, une caméra ou une patrouille surgit et menace de voir ta vraie apparence, reviens en V sans PA. Ce qui a été vu reste vu. Ne coupe pas une attaque en cours.","texte_reference":"Lorsqu’un nouvel observateur, une camera, une patrouille ou une situation inattendue menace soudainement d''exposer la véritable apparence du personnage, revenez immédiatement en V sans PA. Cela n''efface pas ce qui a déjà été vu et ne peut pas interrompre la résolution d''une attaque entrante pour obtenir une immunite.","lore":"Quand un nouvel observateur menace soudain d’exposer la Vérité, le réflexe de Continuité consiste à revenir au Voilé avant d’y réfléchir. Ce mouvement ne retire jamais de la mémoire ce qui a déjà été aperçu.","groupe_actuel":"Silcenters et HDS › Protocoles de Continuité — 7 PTV","statut_regle":"correction","changements":"Les quatre talents existent sous les mêmes noms chez les Extrals : doublon admis (A4), textes d''origine gardés. *Retiré le 30/10* : la restriction « un cran à la fois » que j''avais ajoutée pour les distinguer. Coordination de Silcenter : elle passe par les codes du Silcenter, à la voix ou aux signes. Révélation drillée et Repli réflexe : fréquence 1/scène reprise du tableau."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-coordination-de-silcenter', 'Coordination de Silcenter', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, 1 PA","activation":"1 PA","texte_court":"en combat, tu fournis l''Assistance normale (+2) à un allié sur un test non offensif, si tu as la Compétence à 1 ou plus. Les codes du Silcenter passent par la voix ou les signes : l''allié n''a pas besoin de te voir. Jamais sur une attaque, une Défense active ou un pouvoir personnel.","texte_reference":"Le personnage peut fournir l''Assistance normale (+2) en combat sur un test non offensif d''un’allié, malgré l''interdiction générale de l''Assistance en combat. Il doit posséder la Compétence à 1+, être réellement capable d''aider et dépenser 1 PA. Ne s''applique jamais à une attaque, une Défense active ou un pouvoir strictement personnel.","lore":"Les Silcenters ont appris à aider en pleine crise sans prétendre assister une attaque. Une compétence pertinente peut soutenir le test technique ou opérationnel d’un allié lorsque le personnage consacre réellement une part de son action à cette aide.","groupe_actuel":"Silcenters et HDS › Protocoles de Continuité — 7 PTV","statut_regle":"correction","changements":"Les quatre talents existent sous les mêmes noms chez les Extrals : doublon admis (A4), textes d''origine gardés. *Retiré le 30/10* : la restriction « un cran à la fois » que j''avais ajoutée pour les distinguer. Coordination de Silcenter : elle passe par les codes du Silcenter, à la voix ou aux signes. Révélation drillée et Repli réflexe : fréquence 1/scène reprise du tableau."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-transition-en-chaine', 'Transition en chaîne', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R, 1/scène","activation":"1/scène — durée : scène","texte_court":"jusqu''à la fin de la scène, tes transitions personnelles sont gratuites, aux moments où une transition est possible.","texte_reference":"Une fois par scène, vos transitions personnelles V/SR/R sont gratuites jusqu’à la fin de la scène, seulement aux moments où une transition est normalement possible. Aucun soin, PA, changement forcé d’autrui ou contournement d’un blocage n’est créé.","lore":"Pendant quelques secondes, les transitions successives cessent de casser le rythme d’action. Le personnage peut naviguer entre ses états personnels aux moments permis par la scène, sans créer d’interruptions ni révéler quelqu’un d’autre.","groupe_actuel":"Silcenters et HDS › Protocoles de Continuité — 7 PTV","statut_regle":"correction","changements":"Transition’en chaîne renommé Transition en chaîne."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_union_elfique_et_silcenters', 'Union Elfique et Silcenters', NULL, '{"nature":"exile","chemin":["Traditions de Vérité","Union Elfique et Silcenters"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_union_elfique_et_silcenters_hds_hologram_distorsion_skill', 'HDS — Hologram Distorsion Skill', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Voir la question 2 pour HDP."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-lecture-de-distorsion', 'Lecture de distorsion', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, 1 PA","activation":"Actif — 1 PA — 10 m","texte_court":"Volonté + Maîtrise spirituelle localise une tension active de l''Hologramme à 10 m. Ne montre pas la vraie forme d''un Voilé.","texte_reference":"Pour 1 PA, Volonté + Maîtrise spirituelle localise une tension active de l’Hologramme à 10 m maximum. Ne révèle pas la vraie morphologie d’une cible simplement Voilée.","lore":"Un Silcenter entraîné sent les endroits où l’Hologramme travaille anormalement fort. Transition, HDS ou manifestation qui force le Voile deviennent localisables à courte portée sans révéler automatiquement ce qui se cache dessous.","groupe_actuel":"Silcenters et HDS › HDS — Hologram Distorsion Skill — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-hdb-hologram-distorsion-block', 'Bloquer (HDB)', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, 1 PA, maintien 1 PA/round","activation":"Actif — 1 PA — maintien 1 PA/round — 10 m","texte_court":"Volonté + Maîtrise spirituelle contre la Défense occulte d''une cible visible à 10 m. En cas de réussite, elle ne peut pas passer volontairement à un état plus Révélé avant ton prochain round. Aucun retour forcé en V.","texte_reference":"Pour 1 PA, opposez Volonté + Maîtrise spirituelle à la Défense occulte d’une cible visible à 10 m ; une réussite interdit sa progression volontaire vers un état plus Révélé jusqu’à votre prochain round. Le maintien coûte 1 PA par round ; aucun R→V forcé.","lore":"Le HDB tend localement l’Hologramme autour d’une créature et rend plus difficile le passage vers un état plus Révélé. La cible conserve sa volonté, mais chaque tentative doit désormais pousser contre la distorsion imposée.","groupe_actuel":"Silcenters et HDS › HDS — Hologram Distorsion Skill — 6 PTV","statut_regle":"correction","changements":"HDB - Hologram Distorsion Block renommé Bloquer (HDB)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-hdp-hologram-distorsion-punishment', 'Punir (HDP)', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R, réaction, 1 PA, 1/round","activation":"Réaction — 1 PA — 1/round — 10 m","texte_court":"quand une cible visible à 10 m utilise volontairement une capacité SR/R, Volonté + Maîtrise spirituelle contre sa Défense occulte. En cas de réussite, elle subit 1 + DR dégâts de contrainte. L''armure physique ne protège pas. Une observation par capteur ne déclenche rien.","texte_reference":"Une fois par round, dépensez 1 PA en Réaction lorsqu’une cible visible à 10 m utilise volontairement une capacité SR/R incompatible avec la Réalité : Volonté + Maîtrise spirituelle contre sa Défense occulte lui inflige 1 + DR dégâts de contrainte en réussite. L’armure physique ne protège pas ; une observation par capteur ne déclenche rien.","lore":"Le HDP utilise la réaction de l’Hologramme comme sanction contre une manifestation trop incompatible avec la Réalité. La contrainte frappe directement celui qui force le Voile, indépendamment d’une armure purement physique.","groupe_actuel":"Silcenters et HDS › HDS — Hologram Distorsion Skill — 6 PTV","statut_regle":"correction","changements":"HDP - Hologram Distorsion Punishment renommé Punir (HDP)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_croix_d_emphyrra', 'Croix d''Emphyrra', NULL, '{"nature":"exile","chemin":["Traditions de Vérité","Croix d''Emphyrra"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_croix_d_emphyrra_serpentaire_de_citrine_haute_magie_de_citrine', 'Serpentaire de Citrine · Haute Magie de Citrine', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Réfection vitale : la note de développement est retirée (« proposition de nouvelle limite », « rechargement de page »). Réfection vitale : la fréquence « 1/scénario par bénéficiaire » devient 1/scène pour le soigneur (simplification, marquée). Il n''y a plus de registre sur la fiche d''autrui. Le total de soins sur un scénario reste proche, mais un seul soin est possible par combat. Correction somatique : prérequis Suture conservé ; elle prend rang après Réfection vitale."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-suture', 'Suture', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":"1 PA","texte_court":"au contact, tu stabilises une hémorragie ou une blessure qu''un soin ordinaire pourrait stabiliser. Un Agonisant est Stabilisé, si rien ne l''empêche.","texte_reference":"Au contact d''une creature vivante, stabilisez automatiquement une hémorragie ou une blessure qui pourrait être stabilisee par des soins physiques ordinaires. Sur un Agonisant, le Talent le Stabilise si rien ne rend la stabilisation impossible.","lore":"La Suture arrête immédiatement ce que des soins ordinaires sauraient fermer s’ils disposaient du temps nécessaire. Hémorragie et plaie stabilisable sont prises en charge avant que leur urgence ne devienne la cause de la mort.","groupe_actuel":"Croix d''Emphyrra › Serpentaire de Citrine — 22 PTV › Haute Magie de Citrine — 8 PTV","statut_regle":"correction","changements":"Réfection vitale : la note de développement est retirée (« proposition de nouvelle limite », « rechargement de page »). Réfection vitale : la fréquence « 1/scénario par bénéficiaire » devient 1/scène pour le soigneur (simplification, marquée). Il n''y a plus de registre sur la fiche d''autrui. Le total de soins sur un scénario reste proche, mais un seul soin est possible par combat. Correction somatique : prérequis Suture conservé ; elle prend rang après Réfection vitale."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-refection-vitale', 'Réfection vitale', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène","activation":"Actif — 1 PA — 1/scénario/bénéficiaire","texte_court":"au contact, Volonté + Maîtrise spirituelle difficulté 18. La cible récupère 4 + DR PV, sans dépasser son maximum.","texte_reference":"Pour 1 PA au contact, Volonté + Maîtrise spirituelle difficulté 18 rend 4 + DR PV, sans dépasser le maximum. Une même cible ne peut en bénéficier qu’une fois par scénario.\nProposition de nouvelle limite par cible/scénario, inspirée de l’arbitrage sur les nanites ; un autre lanceur ou un rechargement de page ne doit pas renouveler ce même soin sur la cible.\nLe suivi est porté par le bénéficiaire, indépendamment du lanceur ; aucune recharge au combat suivant, au rechargement de page ou à une transition V/SR/R.","lore":"Au contact, la magie de Citrine rappelle au corps son état intact et l’aide à reconstruire une part de ce qui vient d’être perdu. Le soin reste limité par ce que la vie présente peut encore soutenir.","groupe_actuel":"Croix d''Emphyrra › Serpentaire de Citrine — 22 PTV › Haute Magie de Citrine — 8 PTV","statut_regle":"correction","changements":"Réfection vitale : la note de développement est retirée (« proposition de nouvelle limite », « rechargement de page »). Réfection vitale : la fréquence « 1/scénario par bénéficiaire » devient 1/scène pour le soigneur (simplification, marquée). Il n''y a plus de registre sur la fiche d''autrui. Le total de soins sur un scénario reste proche, mais un seul soin est possible par combat. Correction somatique : prérequis Suture conservé ; elle prend rang après Réfection vitale."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-correction-somatique', 'Correction somatique', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R, 2 PA","activation":"Actif — 2 PA — contact","texte_court":"au contact, Volonté + Maîtrise spirituelle contre la gravité du trouble (15 courant, 18 complexe) ou contre sa Puissance. Un trouble mineur récent cesse ; un trouble plus profond est contenu pour la scène. Ne rend aucun PV et ne supprime aucune Nature.","texte_reference":"Pour 2 PA au contact, opposez Volonté + Maîtrise spirituelle à la gravité du trouble ou à sa Puissance : 15 pour un trouble ordinaire courant, 18 pour un cas complexe. En réussite, un trouble mineur récent cesse ; un trouble plus profond est contenu pour la scène, sans soin de PV ni suppression d’une Nature.","lore":"La Haute Magie de Citrine traite certaines perturbations corporelles comme un système que l’on peut réaccorder. Poison, spasme ou dysfonction récente sont contenus ou corrigés sans que le sort prétende réparer les blessures déjà subies.","groupe_actuel":"Croix d''Emphyrra › Serpentaire de Citrine — 22 PTV › Haute Magie de Citrine — 8 PTV","statut_regle":"correction","changements":"Réfection vitale : la note de développement est retirée (« proposition de nouvelle limite », « rechargement de page »). Réfection vitale : la fréquence « 1/scénario par bénéficiaire » devient 1/scène pour le soigneur (simplification, marquée). Il n''y a plus de registre sur la fiche d''autrui. Le total de soins sur un scénario reste proche, mais un seul soin est possible par combat. Correction somatique : prérequis Suture conservé ; elle prend rang après Réfection vitale."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-restauration-parfaite', 'Restauration parfaite', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1/scénario, plusieurs heures","activation":"1/Scénario - rituel long","texte_court":"tu restaures un dommage organique majeur encore compatible avec la survie (tissu détruit, organe lésé, membre perdu). Pas de résurrection, et rien ne repousse à la place d''une augmentation.","texte_reference":"Avec plusieurs heures de soin et un’environnement adapte, restaurez un dommage organique majeur encore compatible avec la survie : tissu détruit, organe gravement lésé ou membre perdu. Le Talent ne ressuscite pas un mort, ne recree pas une partie remplacee volontairement par une augmentation et peut demander une convalescence narrative.","lore":"Des heures de travail permettent à Citrine d’aller bien au-delà du soin de combat. Tissus, organe ou membre encore compatibles avec la survie peuvent être reconstruits comme une restauration méthodique du vivant.","groupe_actuel":"Croix d''Emphyrra › Serpentaire de Citrine — 22 PTV › Haute Magie de Citrine — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_croix_d_emphyrra_aigle_de_larvikite_intransigeance', 'Aigle de Larvikite · Intransigeance', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Une fois suffit : « facilitée d''un niveau sur un seuil fixe » est remplacé par +3. La valeur est la même, mais il n''y a plus de seconde échelle de bonus. Rappeler à lui : prérequis ajouté (ordre de la voie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-aucune-reverence', 'Aucune révérence', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"+3 pour résister à une pression sociale ou surnaturelle fondée sur le sacré, la noblesse, la divinité, la prophétie ou l''autorité religieuse.","texte_reference":"Circonstances favorables (+3) pour resister à une pression sociale ou surnaturelle qui repose explicitement sur le statut sacré, la noblesse, la divinité, la prophetie ou une autorite religieuse revendiquee.","lore":"L’Aigle de Larvikite a appris à regarder rois, prophètes et dieux sans baisser les yeux par réflexe. Un titre sacré ou une aura de noblesse doit encore prouver qu’il mérite d’être obéi.","groupe_actuel":"Croix d''Emphyrra › Aigle de Larvikite — 15 PTV › Intransigeance — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-une-fois-suffit', 'Une fois suffit', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif — après résistance réussie","texte_court":"après une résistance réussie, +3 aux nouvelles résistances contre le même effet de la même source, jusqu''à la fin de la scène.","texte_reference":"Après résistance réussie, les nouvelles résistances contre le même effet de la même source sont facilitées d’un niveau sur un seuil fixe ; en opposition, appliquez une seule circonstance favorable de +3. Le bénéfice cesse à la fin de la scène et ne s’ajoute pas à un autre +3 équivalent.","lore":"Une domination déjà vaincue perd une partie de son mystère. L’Aigle retient la sensation exacte de la pression et résiste plus facilement au même procédé tant que la source n’a pas changé de méthode.","groupe_actuel":"Croix d''Emphyrra › Aigle de Larvikite — 15 PTV › Intransigeance — 8 PTV","statut_regle":"correction","changements":"Une fois suffit : « facilitée d''un niveau sur un seuil fixe » est remplacé par +3. La valeur est la même, mais il n''y a plus de seconde échelle de bonus. Rappeler à lui : prérequis ajouté (ordre de la voie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-rappeler-a-lui', 'Rappeler à lui', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R, 1 PA","activation":"1 PA","texte_court":"un allié qui t''entend et qui résiste à une peur, une fascination, une domination ou une pression religieuse surnaturelle reçoit l''Assistance (+2), même en combat.","texte_reference":"Un’allié qui peut entendre le personnage et qui résiste à une peur, une fascination, une domination ou une pression religieuse surnaturelle peut recevoir Assistance +2, y compris en combat, si le personnage dépense 1 PA et peut réellement le ramenér a ses propres convictions.","lore":"Quand un compagnon commence à céder, l’Aigle le ramène à ce qu’il sait de lui-même : nom, convictions, engagements. Cette voix familière devient une assistance véritable contre l’emprise qui cherche à parler plus fort.","groupe_actuel":"Croix d''Emphyrra › Aigle de Larvikite — 15 PTV › Intransigeance — 8 PTV","statut_regle":"correction","changements":"Une fois suffit : « facilitée d''un niveau sur un seuil fixe » est remplacé par +3. La valeur est la même, mais il n''y a plus de seconde échelle de bonus. Rappeler à lui : prérequis ajouté (ordre de la voie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-liturgie-du-refus', 'Liturgie du refus', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène","activation":"Actif — 1 PA — 1/scène","texte_court":"jusqu''à trois alliés qui t''entendent gagnent +3 contre la domination, la peur, la fascination et le commandement surnaturels, jusqu''à la fin de la scène.","texte_reference":"Pour 1 PA, une fois par scène, jusqu’à trois alliés entendant la liturgie gagnent +3 contre domination, peur, fascination et commandement surnaturels pour la scène. Les bonus de résistance équivalents ne se cumulent pas.","lore":"La liturgie de Larvikite rappelle à ceux qui l’entendent que la volonté leur appartient encore. Quelques phrases scandées suffisent à donner au groupe un point d’appui commun contre peur, fascination et commandement surnaturel.","groupe_actuel":"Croix d''Emphyrra › Aigle de Larvikite — 15 PTV › Intransigeance — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_croix_d_emphyrra_aigle_de_larvikite_rites_des_anciens_dieux', 'Aigle de Larvikite · Rites des anciens dieux', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Rite funéraire : prérequis ajouté (ordre de la voie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-consecration', 'Consécration', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 10 minutes","activation":"Rituel : 10 minutes — 100 m","texte_court":"jusqu''à la fin du scénario, tant que tu restes à 100 m, tu ressens une profanation directe ou une intrusion surnaturelle majeure sur le support consacré. Une consécration à la fois.","texte_reference":"Après dix minutes de consécration, ressentez une profanation directe ou intrusion surnaturelle majeure affectant le support tant que vous restez à 100 m, jusqu’à la fin du scénario. Une consécration suivie à la fois, sans protection physique ni identité révélée.","lore":"Les anciens cultes de Larvikite savaient rendre un lieu reconnaissable à ceux qui l’avaient consacré. Une profanation majeure ou une intrusion spirituelle y résonne comme une blessure infligée à quelque chose dont le pratiquant connaît intimement la forme.","groupe_actuel":"Croix d''Emphyrra › Aigle de Larvikite — 15 PTV › Rites des anciens dieux — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-rite-funeraire', 'Rite funéraire', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"SR/R, 10 minutes","activation":"Rituel : 10 minutes","texte_court":"ton résultat de Volonté + Maîtrise spirituelle sert de Puissance contre la possession, l''animation ou l''appropriation des restes, tant que le rite reste intact. Il ne contrôle pas l''âme.","texte_reference":"Après dix minutes de rite, le résultat de Volonté + Maîtrise spirituelle sert de Puissance contre une possession, animation ou appropriation ordinaire des restes. Le rite protège les restes tant qu’il demeure intact ; il ne contrôle ni ne rappelle leur âme.","lore":"Le mort reçoit une place et un repos explicites. Tant que le rite tient, le cadavre n’est plus une enveloppe abandonnée que le premier esprit venu peut reprendre sans opposition.","groupe_actuel":"Croix d''Emphyrra › Aigle de Larvikite — 15 PTV › Rites des anciens dieux — 7 PTV","statut_regle":"correction","changements":"Rite funéraire : prérequis ajouté (ordre de la voie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-rite-de-separation', 'Rite de séparation', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 2 PA au contact ou 10 minutes","activation":"Rituel : 2 PA ou 10 minutes — contact","texte_court":"Volonté + Maîtrise spirituelle contre la Puissance d''un lien spirituel mineur identifié. En cas de réussite, le lien est rompu. Aucune entité n''est détruite et aucune Corruption n''est retirée.","texte_reference":"En 2 PA au contact, ou dix minutes hors pression, opposez Volonté + Maîtrise spirituelle à la Puissance du lien spirituel mineur identifié pour le rompre. Aucune entité, Nature ou Marque fondamentale n’est détruite et aucun point de Corruption n’est directement retiré.","lore":"Le rite cherche le fil qui relie encore une présence étrangère à son support. Une fois identifié, ce lien mineur peut être coupé proprement sans prétendre détruire l’entité située à l’autre extrémité.","groupe_actuel":"Croix d''Emphyrra › Aigle de Larvikite — 15 PTV › Rites des anciens dieux — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-rupture-de-l-idole', 'Rupture de l''idole', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":"Actif — 2 PA — 1/scène","texte_court":"Volonté + Maîtrise spirituelle contre la Puissance du lien d''un support cultuel identifié. Le lien est interrompu jusqu''à la fin de la scène, et définitivement si le support est détruit.","texte_reference":"Pour 2 PA, une fois par scène, opposez Volonté + Maîtrise spirituelle à la Puissance du lien d’un support cultuel identifié pour l’interrompre jusqu’à la fin de la scène. La rupture ne devient définitive que si son support indispensable est réellement détruit ; l’entité liée n’est pas blessée automatiquement.","lore":"Larvikite enseigne qu’un pouvoir soutenu par un objet ou un autel peut être privé de sa voix. Briser le lien du support interrompt ce qu’il alimentait, même si la puissance qui l’avait consacré existe encore ailleurs.","groupe_actuel":"Croix d''Emphyrra › Aigle de Larvikite — 15 PTV › Rites des anciens dieux — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_croix_d_emphyrra_hibou_d_onyx_science_des_ombres', 'Hibou d''Onyx · Science des Ombres', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte (courte)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Main d''Onyx prend rang après Lire l''ancrage. Main d''Onyx, Rune de Fer et Arme d''Interférence se ressemblent. Elles restent distinctes par leur source : le corps (Hibou), une rune sur l''objet (Runes) ou un prototype (Technomagie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-regard-d-onyx', 'Regard d''Onyx', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Passif","texte_court":"tu perçois les Ombres, les esprits et les manifestations immatérielles qui ne sont pas explicitement dissimulés. Tu n''apprends ni leur identité ni leur puissance.","texte_reference":"Le personnage peut percevoir directement les Ombres, esprits et manifestations immatérielles presentes dans son’environnement lorsqu’elles ne sont pas explicitement dissimulées. Il ne connait pas automatiquement leur identité, leurs intentions ou leur puissance.","lore":"Les Ombres et présences immatérielles cessent de dépendre de leur bonne volonté pour être vues. Le regard d’Onyx les perçoit comme des êtres présents, sans leur attribuer automatiquement identité ou intention.","groupe_actuel":"Croix d''Emphyrra › Hibou d''Onyx — 15 PTV › Science des Ombres — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-lire-l-ancrage', 'Lire l''ancrage', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":"1 PA","texte_court":"Esprit + Perception sur une Ombre t''apprend ce qui la retient (lieu, objet, personne, pacte, corps, émotion). Le DR affine.","texte_reference":"En observant une Ombre ou une manifestation immatérielle, Esprit + Perception permet d''identifier la grande nature de ce qui la retient au monde : lieu, objet, personne, pacte, corps, emotion ou autre support. Le DR affine sans révéler nécessairement comment détruire l''ancrage.","lore":"Le Hibou d’Onyx observe une Ombre comme on observe une plante pour trouver sa racine. Lieu, objet, personne ou émotion qui la retient au monde laisse une relation perceptible même si la méthode pour la rompre reste inconnue.","groupe_actuel":"Croix d''Emphyrra › Hibou d''Onyx — 15 PTV › Science des Ombres — 7 PTV","statut_regle":"correction","changements":"Main d''Onyx prend rang après Lire l''ancrage. Main d''Onyx, Rune de Fer et Arme d''Interférence se ressemblent. Elles restent distinctes par leur source : le corps (Hibou), une rune sur l''objet (Runes) ou un prototype (Technomagie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-main-d-onyx', 'Main d''Onyx', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R","activation":"Passif","texte_court":"tu touches, saisis ou frappes une Ombre comme si elle était matérielle, avec tes caractéristiques normales, sans bonus.","texte_reference":"Le personnage peut toucher, saisir ou frapper une Ombre ou une manifestation immatérielle comme si elle possedait une présence physique. Ses attaques utilisent leurs caracteristiques normales et n''obtiennent aucun bonus de dégâts.","lore":"L’Onyx enseigne au corps à rencontrer ce qui n’a normalement pas de chair. La main, l’arme ou la prise trouve une présence là où un combattant ordinaire ne sentirait que du vide.","groupe_actuel":"Croix d''Emphyrra › Hibou d''Onyx — 15 PTV › Science des Ombres — 7 PTV","statut_regle":"correction","changements":"Main d''Onyx prend rang après Lire l''ancrage. Main d''Onyx, Rune de Fer et Arme d''Interférence se ressemblent. Elles restent distinctes par leur source : le corps (Hibou), une rune sur l''objet (Runes) ou un prototype (Technomagie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-refuser-l-arrachement', 'Refuser l''arrachement', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"c","acces":"R, réaction, 1 PA, 1/scène","activation":"Réaction — 1 PA — 1/scène","texte_court":"Volonté + Maîtrise spirituelle contre la Puissance d''un arrachement spirituel qui vise toi ou un allié au contact. En cas de réussite, il échoue. N''expulse pas un esprit déjà installé.","texte_reference":"Une fois par scène, pour 1 PA en Réaction, opposez Volonté + Maîtrise spirituelle à la Puissance d’un arrachement spirituel visant vous-même ou un allié au contact. Une réussite empêche cet arrachement, sans expulser un esprit déjà installé.","lore":"Quand une force tente de tirer l’âme hors du corps ou d’emporter un esprit ailleurs, le Hibou oppose sa propre volonté comme une prise. Au contact, il peut offrir cette même résistance à un compagnon menacé.","groupe_actuel":"Croix d''Emphyrra › Hibou d''Onyx — 15 PTV › Science des Ombres — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_croix_d_emphyrra_hibou_d_onyx_symbiose_d_onyx', 'Hibou d''Onyx · Symbiose d''Onyx', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Pas d''Onyx : fréquence 1/scène reprise du tableau. Chair intermittente prend rang après Pas d''Onyx."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-empreinte-d-onyx', 'Empreinte d''Onyx', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Passif — 20 m","texte_court":"tu gardes jusqu''à la fin du scénario une empreinte issue d''une Ombre consentante ou d''une trace stable. Elle t''indique la direction d''un passage ou d''une concentration d''Ombres à 20 m.","texte_reference":"Conservez une seule empreinte issue d’une Ombre consentante ou d’une trace stable jusqu’à la fin du scénario. Elle indique approximativement la direction d’un passage ou d’une concentration d’Ombres à 20 m, sans localisation lointaine d’un individu.","lore":"Un contact volontaire avec une Ombre peut laisser une résonance durable. Le porteur conserve cette trace comme une boussole imparfaite vers d’autres concentrations d’Onyx ou des passages proches de leur plan.","groupe_actuel":"Croix d''Emphyrra › Hibou d''Onyx — 15 PTV › Symbiose d''Onyx — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-pas-d-onyx', 'Pas d''Onyx', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/scène","activation":"1/Scène - pendant un Déplacement","texte_court":"pendant un Déplacement, tu traverses jusqu''à 1 m de matière ordinaire si tu connais ou perçois un espace libre derrière. Tu ne peux pas rester dans la matière.","texte_reference":"Traversez jusqu''à 1 mètre de matière non surnaturelle continue pendant un Déplacement, à condition de connaitre ou percevoir un espace libre de l''autre côté. Le Talent ne permet pas de rester dans la matière ni de franchir une barrière dimensionnelle.","lore":"Le Pas d’Onyx utilise l’immatérialité pour franchir une épaisseur brève, pas pour habiter la matière. Le Hibou glisse à travers le mur uniquement s’il sait qu’un espace libre l’attend vraiment de l’autre côté.","groupe_actuel":"Croix d''Emphyrra › Hibou d''Onyx — 15 PTV › Symbiose d''Onyx — 8 PTV","statut_regle":"correction","changements":"Pas d''Onyx : fréquence 1/scène reprise du tableau. Chair intermittente prend rang après Pas d''Onyx."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-chair-intermittente', 'Chair intermittente', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R, réaction, 1 PA, 1/scène","activation":"Réaction — 1 PA, défense incluse — 1/scène","texte_court":"+3 à une Défense active contre une attaque purement physique (le PA paie la défense), ou tu laisses un petit obstacle traverser ton corps.","texte_reference":"Une fois par scène, pour 1 PA en Réaction, obtenez +3 à une Défense active contre une attaque purement physique, ce PA comprenant la défense, ou laissez traverser un petit obstacle par votre corps. Les effets surnaturels et biphysiques restent applicables.","lore":"La Symbiose d’Onyx apprend à la chair à ne pas être entièrement matérielle au mauvais moment. Un choc ou un petit obstacle peut traverser le corps rendu brièvement incertain, tandis qu’un pouvoir capable de toucher l’immatériel conserve toute sa prise.","groupe_actuel":"Croix d''Emphyrra › Hibou d''Onyx — 15 PTV › Symbiose d''Onyx — 8 PTV","statut_regle":"correction","changements":"Pas d''Onyx : fréquence 1/scène reprise du tableau. Chair intermittente prend rang après Pas d''Onyx."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-entre-deux-etats', 'Entre deux états', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène","activation":"Actif — 1 PA — 1/scène","texte_court":"tu restes semi-immatériel jusqu''à la fin de la scène. Tu traverses les personnes et les obstacles minces en te déplaçant, avec +3 à tes Défenses actives contre le purement physique. Pendant ce temps, aucune attaque physique ni manipulation lourde. Tu y mets fin au début de ton activation.","texte_reference":"Pour 1 PA, une fois par scène, restez semi-immatériel jusqu’à la fin de la scène : traversez personnes et obstacles minces pendant vos déplacements et gagnez +3 à vos Défenses actives contre le purement physique. Tant que l’état dure, aucune attaque physique ou manipulation lourde ; vous pouvez y mettre fin au début de votre activation.\nLa Défense reste payante ; ni invulnérabilité, ni franchissement illimité de matière, ni passage à travers une barrière dimensionnelle. Une sortie doit être physiquement possible.","lore":"Pendant quelques secondes, le corps demeure partagé entre matière et Ombre. Il peut traverser des personnes ou des parois minces et devient plus difficile à frapper physiquement, au prix d’une relation beaucoup plus faible avec les objets solides.","groupe_actuel":"Croix d''Emphyrra › Hibou d''Onyx — 15 PTV › Symbiose d''Onyx — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_heritages_whurtens', 'Héritages whurtens', NULL, '{"nature":"exile","chemin":["Traditions de Vérité","Héritages whurtens"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_heritages_whurtens_runes_whurtennes', 'Runes whurtennes', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte (Runes de base au choix)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Le bloc « Runes : dix minutes… », recopié dans six entrées, devient la Règle des Runes. Rune de Garde : « 1/scénario par bénéficiaire » devient 1/scénario pour le runiste (simplification, marquée, plus stricte qu''avant). Le suivi sur la fiche du porteur disparaît. Phrase runique : jargon de serveur retiré (« contrôlées par identifiants »). Entrée obligatoire par une Rune de palier I : aujourd''hui, on pouvait commencer par une Rune à 2 PTV."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-rune-du-foyer', 'Rune du Foyer', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Inscription : 10 minutes — 100 m","texte_court":"liée à un refuge, elle te fait ressentir, à 100 m au plus, une intrusion violente, un incendie, une destruction importante ou une manifestation majeure. Elle n''identifie pas l''auteur.","texte_reference":"Après dix minutes d’inscription, liez un refuge à vous pour le scénario : à 100 m maximum, ressentez intrusion violente, incendie, destruction importante ou manifestation majeure. Une Rune du Foyer active par runiste ; aucun auteur identifié.\nRunes : dix minutes d’inscription ordinaire ; une seule inscription active de chaque type par runiste. Durée du scénario, sauf Phrase durable ; une Phrase brève reste limitée à la scène. La Rune de Garde consommée ne se recharge jamais par changement de support ou d’auteur.","lore":"Le Foyer runique relie le Whurten à un refuge qu’il a explicitement désigné. Incendie, intrusion violente ou manifestation majeure y résonnent jusqu’à lui comme une alarme lointaine tant que la distance reste raisonnable.","groupe_actuel":"Héritages whurtens › Runes whurtennes — 13 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-rune-de-veille', 'Rune de Veille', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"SR/R","activation":"Inscription : 10 minutes — 100 m","texte_court":"une condition simple (franchir, ouvrir, déplacer) déclenche une alerte mentale à 100 m au plus. Aucune vision de l''événement.","texte_reference":"Après dix minutes d’inscription, une condition simple de franchissement, ouverture ou déplacement déclenche une alerte mentale à 100 m maximum, jusqu’à la fin du scénario. Une Rune de Veille active par runiste ; aucune vision de l’événement.\nRunes : dix minutes d’inscription ordinaire ; une seule inscription active de chaque type par runiste. Durée du scénario, sauf Phrase durable ; une Phrase brève reste limitée à la scène. La Rune de Garde consommée ne se recharge jamais par changement de support ou d’auteur.","lore":"La Rune de Veille transforme un passage ou un objet en témoin simple. Quand la condition définie se produit, le praticien ressent l’événement sans recevoir de vision ni d’identité de celui qui l’a déclenché.","groupe_actuel":"Héritages whurtens › Runes whurtennes — 13 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-rune-de-fer', 'Rune de Fer', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":"Inscription : 10 minutes","texte_court":"une arme ou un outil que tu possèdes ou qu''on te confie peut toucher l''immatériel, sans bonus de jet ni de dégâts.","texte_reference":"Après dix minutes d’inscription, une arme ou un outil peut interagir avec l’immatériel pour le scénario, sans bonus de jet ou de dégâts. Une Rune de Fer active par runiste, sur un objet réellement possédé ou confié.\nRunes : dix minutes d’inscription ordinaire ; une seule inscription active de chaque type par runiste. Durée du scénario, sauf Phrase durable ; une Phrase brève reste limitée à la scène. La Rune de Garde consommée ne se recharge jamais par changement de support ou d’auteur.","lore":"La Rune de Fer donne à une arme ou un outil une prise sur ce qui refuse la matière. Le métal ou le bois ne devient pas plus dangereux ; il cesse simplement d’être ignoré par Ombres et manifestations intangibles.","groupe_actuel":"Héritages whurtens › Runes whurtennes — 13 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-rune-de-scellement', 'Rune de Scellement', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R","activation":"Inscription : 10 minutes","texte_court":"une fermeture oppose une difficulté 18 à toute ouverture par la force, la magie ou l''intangibilité. Détruire le support reste possible.","texte_reference":"Après dix minutes d’inscription, une fermeture réelle oppose une difficulté 18 à son ouverture par force, magie ou intangibilité, pour le scénario. Une Rune de Scellement active par runiste ; détruire le support reste possible.\nRunes : dix minutes d’inscription ordinaire ; une seule inscription active de chaque type par runiste. Durée du scénario, sauf Phrase durable ; une Phrase brève reste limitée à la scène. La Rune de Garde consommée ne se recharge jamais par changement de support ou d’auteur.","lore":"La Rune de Scellement ajoute une fermeture surnaturelle à une porte ou un contenant déjà clos. Force, magie ou immatérialité doivent alors vaincre ce verrou de sens, même si détruire matériellement tout le support reste toujours possible.","groupe_actuel":"Héritages whurtens › Runes whurtennes — 13 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-rune-de-garde', 'Rune de Garde', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"c","acces":"R, 1/scénario","activation":"Inscription : 10 minutes — 1/scénario/bénéficiaire","texte_court":"le porteur réduit de 6 les dégâts de la première atteinte surnaturelle qu''il subit (minimum 0), puis la Rune s''éteint.","texte_reference":"La Rune réduit de 6 les dégâts de la première atteinte surnaturelle subie, minimum 0, puis s’éteint. Un bénéficiaire ne peut recevoir cette protection qu’une fois par scénario, même après réinscription.\nInscription normale de dix minutes ; une Rune de Garde active par runiste. La protection n’est pas remise à zéro par une nouvelle scène ou un nouveau support.\nRunes : dix minutes d’inscription ordinaire ; une seule inscription active de chaque type par runiste. Durée du scénario, sauf Phrase durable ; une Phrase brève reste limitée à la scène. La Rune de Garde consommée ne se recharge jamais par changement de support ou d’auteur.\nLe suivi est porté par le bénéficiaire : nouveau lanceur, nouveau combat, réinscription, sauvegarde et changement V/SR/R ne renouvellent pas cette protection.","lore":"Inscrite sur ce qui protège le corps, la Rune de Garde absorbe une part du premier choc surnaturel qu’elle rencontre. Une fois cette charge dépensée, le symbole n’est plus qu’une trace éteinte jusqu’à réinscription.","groupe_actuel":"Héritages whurtens › Runes whurtennes — 13 PTV","statut_regle":"correction","changements":"Le bloc « Runes : dix minutes… », recopié dans six entrées, devient la Règle des Runes. Rune de Garde : « 1/scénario par bénéficiaire » devient 1/scénario pour le runiste (simplification, marquée, plus stricte qu''avant). Le suivi sur la fiche du porteur disparaît. Phrase runique : jargon de serveur retiré (« contrôlées par identifiants »). Entrée obligatoire par une Rune de palier I : aujourd''hui, on pouvait commencer par une Rune à 2 PTV."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-inscription-breve', 'Inscription brève', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"d","acces":"SR/R, 1 PA, 1/scène ; deux Runes de base requises","activation":"Inscription — 1 PA — 1/scène","texte_court":"tu inscris en 1 PA une Rune de base connue, sur un support accessible et dans l''état qu''elle exige. Elle dure la scène.","texte_reference":"Une fois par scène, inscrivez en 1 PA une Rune de base connue sur un support accessible, en respectant son état V/SR/R. L’inscription expire à la fin de la scène ; il faut avoir acquis deux Runes de base distinctes pour acheter ce talent.","lore":"Une Rune whurtenne peut être tracée très vite lorsqu’on accepte qu’elle ne survive pas à la scène. Le symbole existe physiquement sur son support et porte immédiatement la fonction runique connue.","groupe_actuel":"Héritages whurtens › Runes whurtennes — 13 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-phrase-runique', 'Phrase runique', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R ; trois Runes de base requises","activation":"Inscription : 10 minutes — durable","texte_court":"deux Runes connues compatibles, sur un même support, restent actives tant que l''inscription est intacte, au-delà du scénario. Elles occupent leur inscription unique.","texte_reference":"Une Phrase associe deux Runes connues compatibles sur le même support et en rend l’inscription durable tant qu’elle reste intacte, au-delà de la fin du scénario. Elle occupe l’unique inscription active de chaque Rune et ne recharge pas une Rune de Garde déjà consommée.\nTrois Runes de base distinctes requises, contrôlées par identifiants. La durée durable est nouvelle ; pas de deuxième copie active, de bonus de dégâts ni de contournement de support. Une Phrase tracée par Inscription brève reste limitée à la scène.\nRunes : dix minutes d’inscription ordinaire ; une seule inscription active de chaque type par runiste. Durée du scénario, sauf Phrase durable ; une Phrase brève reste limitée à la scène. La Rune de Garde consommée ne se recharge jamais par changement de support ou d’auteur.","lore":"Deux Runes compatibles peuvent être pensées comme une seule phrase plutôt que deux inscriptions indépendantes. Le support porte simultanément leurs sens sans que l’association permette de dupliquer ce qu’aucune des deux n’aurait pu faire seule.","groupe_actuel":"Héritages whurtens › Runes whurtennes — 13 PTV","statut_regle":"correction","changements":"Le bloc « Runes : dix minutes… », recopié dans six entrées, devient la Règle des Runes. Rune de Garde : « 1/scénario par bénéficiaire » devient 1/scénario pour le runiste (simplification, marquée, plus stricte qu''avant). Le suivi sur la fiche du porteur disparaît. Phrase runique : jargon de serveur retiré (« contrôlées par identifiants »). Entrée obligatoire par une Rune de palier I : aujourd''hui, on pouvait commencer par une Rune à 2 PTV."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_heritages_azmenoriens_technomagie_moderne', 'Héritages azménoriens · Technomagie moderne', NULL, '{"nature":"exile","chemin":["Traditions de Vérité","Héritages azménoriens · Technomagie moderne"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_heritages_azmenoriens_technomagie_moderne_convergence', 'Convergence', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte (courte)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Convertisseur biphysique : prérequis ajouté (ordre de la voie). Convertisseur biphysique : note de serveur retirée (« puissance admissible à enregistrer ») et remplacée par « appareil portatif »."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-capteur-biphysique', 'Capteur biphysique', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Prototype ou adaptation","texte_court":"tu adaptes un capteur réel pour qu''il enregistre la magie active, les perturbations du Flux, les présences immatérielles et les anomalies dimensionnelles. Il signale le phénomène, pas sa nature.","texte_reference":"Adaptez un capteur réel - camera, scanner, détécteur, instrument scientifique - afin qu''il enregistre les manifestations de magie active, les perturbations importantes du Flux, les phénomènes immatériels directement presents et les anomalies dimensionnelles locales. Il indique qu''un phénomène existe sans en donner automatiquement la nature exacte. Les données obtenues peuvent être examinees par un tiers.","lore":"Le Capteur biphysique remarque les phénomènes qui existent à cheval sur plusieurs couches du réel. Magie active, Flux, immatériel ou anomalie dimensionnelle deviennent détectables sans livrer automatiquement leur nature détaillée.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Convergence — 5 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-asservissement-croise', 'Asservissement croisé', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":"Prototype ou adaptation","texte_court":"tu relies une fonction simple et préprogrammée d''un appareil à un déclencheur que ton Capteur sait détecter. Jamais d''attaque automatique.","texte_reference":"Reliez une fonction technologique simple à un déclencheur surnaturel que le Capteur biphysique sait détecter : apparition d''une signature, anomalie dimensionnelle, présence immatérielle, forte perturbation du Flux. La fonction déclenchée doit être préprogrammée et normalement réalisable par l''appareil. Une attaque automatique n''est jamais autorisee par ce Talent.","lore":"La Convergence permet à un phénomène surnaturel détectable de devenir déclencheur d’une fonction technique déjà programmée. La machine exécute ce qu’elle sait faire ; la magie ne lui invente pas un nouvel arsenal.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Convergence — 5 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-convertisseur-biphysique', 'Convertisseur biphysique', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R, 1 PA, 1/scène, concentration","activation":"Actif — 1 PA — 1/scène — concentration","texte_court":"Volonté + Maîtrise spirituelle difficulté 18 alimente un appareil portatif jusqu''à la fin de la scène, sans PA de maintien. Pas de besoin industriel, de propulsion principale ni d''arme lourde énergétique.","texte_reference":"Pour 1 PA, une fois par scène, un test de Volonté + Maîtrise spirituelle difficulté 18 alimente un appareil portatif admissible jusqu’à la fin de la scène, sans PA de maintien. La concentration reste nécessaire et les besoins industriels, propulsions principales et armes lourdes énergétiques restent exclus.\nPuissance admissible à enregistrer avant utilisation ; pas de recharge illimitée d’un stock revendable ni d’énergie conservée après la fin de la conversion.","lore":"La technomagie azménorienne peut tirer d’une manifestation magique assez d’énergie pour alimenter brièvement une petite fonction technique. Cette conversion reste limitée par l’échelle et refuse les besoins démesurés.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Convergence — 5 PTV","statut_regle":"correction","changements":"Convertisseur biphysique : prérequis ajouté (ordre de la voie). Convertisseur biphysique : note de serveur retirée (« puissance admissible à enregistrer ») et remplacée par « appareil portatif »."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_heritages_azmenoriens_technomagie_moderne_fracture', 'Fracture', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Décalage de trajectoire : prérequis Relais conservé ; il prend rang après Fenêtre de phase."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-relais-discontinu', 'Relais discontinu', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":"1 PA","texte_court":"tu établis une liaison de données, de commande ou de communication avec un appareil connu à moins d''1 m, à travers un mur ou un blindage. Pas à travers un chiffrement, un mot de passe ou un appareil éteint.","texte_reference":"Avec un dispositif de transmission, établissez une liaison de données, de commande ou de communication’avec un’appareil connu situé a moins d''un mètre, même si une barrière matérielle empêche la connexion directe. Le Talent contourne mur, blindage ou absence de prise, mais pas chiffrement, mot de passe, sécurité informatique ou appareil éteint.","lore":"Le Relais discontinu crée une liaison de commande ou de données à travers une barrière matérielle courte. Il contourne l’absence de câble ou de prise directe, mais jamais le chiffrement ni les sécurités de l’appareil lui-même.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Fracture — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-fenetre-de-phase', 'Fenêtre de phase', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène","activation":"Actif — 1 PA — 1/scène","texte_court":"jusqu''à la fin de la scène, un capteur voit par un chemin étroit à travers 1 m de matière ordinaire au plus.","texte_reference":"Pour 1 PA, une fois par scène, maintenez jusqu’à la fin de la scène un chemin sensoriel étroit à travers au plus un mètre de matière ordinaire. Le capteur ne produit que ses données normales ; une barrière dimensionnelle ou protection adaptée peut bloquer le passage.","lore":"Une Fenêtre de phase ouvre au capteur un passage sensoriel étroit à travers la matière ordinaire. L’instrument continue de ne mesurer que ce qu’il sait mesurer ; seule la paroi cesse brièvement d’être un obstacle complet.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Fracture — 8 PTV","statut_regle":"correction","changements":"Décalage de trajectoire : prérequis Relais conservé ; il prend rang après Fenêtre de phase."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-decalage-de-trajectoire', 'Décalage de trajectoire', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R, 1/scène","activation":"Attaque payée avec arme préparée — 1/scène","texte_court":"tu décales d''1 m au plus le point de sortie d''une attaque payée avec une arme préparée, vers un espace libre. Aucun bonus d''attaque ni de dégâts. Jamais dans un organisme.","texte_reference":"Une fois par scène, décalez d’au plus un mètre le point de sortie d’une attaque payée utilisant une arme préparée, vers un espace libre réellement exploitable. La cible doit pouvoir être visée ; aucun point de sortie dans un organisme ni bonus de dégâts ou d’attaque.","lore":"La Fracture azménorienne peut déplacer le point où une trajectoire commence réellement. Un projectile ou un rayon quitte alors l’espace depuis un angle légèrement différent, assez pour contourner le bord d’un couvert sans devenir tir aveugle.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Fracture — 8 PTV","statut_regle":"correction","changements":"Décalage de trajectoire : prérequis Relais conservé ; il prend rang après Fenêtre de phase."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-microbreche', 'Microbrèche', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":"Actif — 2 PA — 1/scène","texte_court":"jusqu''à la fin du round suivant, un passage de 20 cm relie deux points connus distants d''1 m au plus. Les objets et les projectiles passent, pas les créatures ni les membres.","texte_reference":"Pour 2 PA, une fois par scène, ouvrez jusqu’à la fin du round suivant un passage de 20 cm entre deux points séparés d’au plus un mètre. Les deux extrémités doivent être connues ; petits objets et projectiles passent, mais ni créature ni membre vivant, et la fermeture ne sectionne rien.\nUn passage actif à la fois ; les tirs, manipulations et déplacements d’objets gardent leurs PA. Aucun portail dans un organisme ou contournement d’une barrière dimensionnelle explicite.","lore":"La Microbrèche relie deux points très proches sans exiger un passage de taille humaine. Son ouverture laisse franchir lumière, son, câble ou petit objet, outil de technomage plus proche d’un trou de serrure impossible que d’un portail de voyage.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Fracture — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_heritages_azmenoriens_technomagie_moderne_arsenal_de_rupture_regard_de_ver', 'Arsenal de Rupture · Regard de Vérité', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Signature de Vérité prend rang après Enregistrement invariant. La mention de l''AIDH (lore) sort du texte joueur. L''Optique reste à 1 PTV : voir la question 5."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-optique-de-verite', 'Optique de Vérité', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Prototype - capteur","texte_court":"tu modifies une caméra, une lunette, un viseur ou un scanner pour qu''il montre la scène sous le Voile. Chaque créature y apparaît selon sa vraie nature, quel que soit son état. Le capteur ne montre ni pouvoirs ni identité. Seule une contre-mesure explicite, comme une HDS adaptée, s''y oppose.","texte_reference":"Modifiez une camera, lunette, viseur, scanner ou capteur compatible afin qu''il interprète la scène sous le Voilé plutot que sa traduction holographique. Les creatures apparaissent selon leur véritable nature et morphologie quel que soit leur état V/SR/R. Le capteur ne révèle ni pouvoirs, ni intentions, ni identité exacte sans connaissance permettant de les interprétér. La Volonté de la cible ne protege pas le Voilé : seule une contre-mesure explicite, telle qu''une HDS adaptée, peut s''opposer au capteur.","lore":"Une caméra ou une lunette équipée d’une Optique de Vérité cesse de prendre le Voile pour la réalité physique. Le capteur enregistre la morphologie réelle sans pour autant devenir lecteur d’identité, de pouvoir ou d’intention.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Arsenal de Rupture — 18 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-enregistrement-invariant', 'Enregistrement invariant', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":"Prototype - stockage","texte_court":"tu protèges un système d''enregistrement. Ce qu''il capte en Vérité n''est plus réécrit par l''Hologramme. Le support peut être détruit ou piraté.","texte_reference":"Protégez un système d''enregistrement afin que les données captées dans la Vérité ne soient pas ensuite réécrites par l’Hologramme. Une image prise par une Optique de Vérité conserve donc la morphologie vraie. Le support peut toujours être détruit, piraté ou neutralise par une contre-mesure spécifique. L''AIDH dispose de versions institutionnelles et industrialisées de ce principe.","lore":"L’Enregistrement invariant protège une donnée contre la réécriture ultérieure de l’Hologramme. Ce qui a été capté sous la Vérité reste inscrit comme tel sur le support, même si le monde autour recommence ensuite à se voiler.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Arsenal de Rupture — 18 PTV","statut_regle":"correction","changements":"Signature de Vérité prend rang après Enregistrement invariant. La mention de l''AIDH (lore) sort du texte joueur. L''Optique reste à 1 PTV : voir la question 5."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-signature-de-verite', 'Signature de Vérité', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Prototype - capteur","texte_court":"après une longue observation à l''Optique, tu enregistres la signature d''une créature. Un capteur préparé la reconnaît ensuite quand elle passe dans son champ, malgré son apparence ou son état.","texte_reference":"Après avoir observé suffisamment longtemps une creature avec une Optique de Vérité, enregistrez sa signature de continuité. Un capteur préparé avec cette signature reconnaît ensuite le même individu lorsqu’il passe réellement dans son champ, malgré un changement d''apparence holographique ou d''état V/SR/R. Ce n''est ni une localisation à distance ni une identification sans observation.","lore":"Une créature suffisamment observée laisse dans le système une continuité reconnaissable au-delà des apparences. Le capteur peut ensuite identifier le même individu lorsqu’il repasse dans son champ malgré les changements V/SR/R.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Arsenal de Rupture — 18 PTV","statut_regle":"correction","changements":"Signature de Vérité prend rang après Enregistrement invariant. La mention de l''AIDH (lore) sort du texte joueur. L''Optique reste à 1 PTV : voir la question 5."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-fenetre-de-verite', 'Fenêtre de Vérité', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Installation réelle et alimentée — 10 m","texte_court":"une installation construite et alimentée diffuse la Vérité locale, dans un rayon de 10 m, sur les écrans et les viseurs qui lui sont reliés. Elle ne change aucun état V/SR/R.","texte_reference":"Une installation construite et alimentée diffuse la Vérité locale à ses écrans et viseurs réellement reliés, dans une zone de 10 m de rayon maximum. Elle ne voit pas à travers les obstacles matériels non couverts par ses capteurs et ne change aucun état V/SR/R.","lore":"La Fenêtre de Vérité traduit en temps réel une petite zone pour les instruments reliés. Elle ne change l’état de personne : elle fournit simplement à l’écran ou au viseur une représentation qui refuse la version holographique.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Arsenal de Rupture — 18 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_heritages_azmenoriens_technomagie_moderne_arsenal_de_rupture_contention_d_', 'Arsenal de Rupture · Contention d''Ombre', NULL, '{"nature":"exile","forme":"une_porte","forme_lot":"collection à une porte, entrée au palier II","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Il n''y a pas de palier I : les coûts d''origine (2, 2, 3, 3) sont conservés. Ancre d''Ombre : « tentatives immatérielles prévues » n''était défini nulle part. La liste est reprise de la Cage de Vérité (correction). Désancrage offensif : « 1/scène par cible » devient 1/scène (simplification, marquée). Cage de Vérité se prend désormais après les deux talents du palier II (avant, il fallait seulement l''Ancre)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-arme-d-interference', 'Arme d''Interférence', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":"Prototype - arme","texte_court":"tu adaptes une arme pour qu''elle affecte normalement les Ombres, les entités déphasées et les phénomènes intangibles. Aucun bonus d''attaque, de dégâts ni de détection.","texte_reference":"Adaptez une arme afin que son’action soit reconnue simultanement par la matière et par certaines manifestations immatérielles. Elle peut affecter normalement Ombres, entites déphasées et phénomènes explicitement intangibles. Elle conserve dégâts, portée et règles normales ; aucun bonus d''attaque, de dégâts ou de détection.","lore":"L’Arme d’Interférence fait reconnaître son impact par matière et immatériel à la fois. Elle ne frappe pas plus fort qu’avant ; elle cesse simplement de traverser les Ombres comme si elles n’étaient pas là.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Arsenal de Rupture — 18 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-ancre-d-ombre', 'Ancre d''Ombre', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R, 1 PA","activation":"Actif — 1 PA — générateur réel — 3 m","texte_court":"un générateur alimenté de 3 m de rayon. Toute tentative d''y passer en immatériel, de se déphaser ou de changer de plan exige Volonté + Force Mentale difficulté 18. Il ne gêne pas le déplacement physique.","texte_reference":"Pour 1 PA, activez un générateur alimenté de 3 m de rayon ; les tentatives immatérielles prévues exigent Volonté + Force Mentale difficulté 18. L’appareil ne bloque pas le déplacement physique normal ni ne contrôle les occupants ; son autonomie est celle du matériel enregistré.","lore":"L’Ancre d’Ombre transforme une zone en mauvais endroit pour fuir par l’immatériel. Une présence qui tente de rompre son lien au plan doit lutter contre un dispositif conçu pour maintenir localement sa continuité.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Arsenal de Rupture — 18 PTV","statut_regle":"correction","changements":"Il n''y a pas de palier I : les coûts d''origine (2, 2, 3, 3) sont conservés. Ancre d''Ombre : « tentatives immatérielles prévues » n''était défini nulle part. La liste est reprise de la Cage de Vérité (correction). Désancrage offensif : « 1/scène par cible » devient 1/scène (simplification, marquée). Cage de Vérité se prend désormais après les deux talents du palier II (avant, il fallait seulement l''Ancre)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-cage-de-verite', 'Cage de Vérité', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Prototype - installation de contention","texte_court":"une enceinte construite. Une créature enfermée qui tente de s''évader par immatérialité, changement de plan, déphasage ou rupture d''ancrage doit réussir Volonté + Force Mentale difficulté 21. Une sortie physique reste possible si la cage s''ouvre ou se brise.","texte_reference":"Construisez une enceinte qui renforce le principe de l''Ancre d''Ombre. Une creature enfermée qui tente une évasion par immaterialite, changement de plan, dephasage ou rupture d''ancrage doit reussir Volonté + Force mentale contre difficulté 21. Une sortie parfaitement physique reste possible si la cage matérielle peut être ouverte ou détruite.","lore":"La Cage de Vérité enferme aussi les voies d’évasion qui n’utilisent pas la porte. Déphasage, immatérialité ou changement de plan rencontrent une résistance technomagique qui oblige la créature à réellement vaincre l’enceinte.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Arsenal de Rupture — 18 PTV","statut_regle":"correction","changements":"Il n''y a pas de palier I : les coûts d''origine (2, 2, 3, 3) sont conservés. Ancre d''Ombre : « tentatives immatérielles prévues » n''était défini nulle part. La liste est reprise de la Cage de Vérité (correction). Désancrage offensif : « 1/scène par cible » devient 1/scène (simplification, marquée). Cage de Vérité se prend désormais après les deux talents du palier II (avant, il fallait seulement l''Ancre)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-desancrage-offensif', 'Désancrage offensif', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":"b","acces":"R, 1/scène","activation":"Après une touche — 1/scène/cible","texte_court":"une touche d''Arme d''Interférence impose la résistance de difficulté 18. En cas d''échec, la cible ne peut plus changer d''ancrage ni sortir de la matière jusqu''à la fin de la scène. Les dégâts restent normaux.","texte_reference":"Une fois par scène par cible, une touche d’Arme d’Interférence déclenche la résistance de difficulté 18 prévue ; en échec, les sorties ou changements d’ancrage concernés sont bloqués pour la scène. Les dégâts de l’arme restent normaux, la Nature n’est pas supprimée et une cible déjà immatérielle n’est pas automatiquement matérialisée.","lore":"Une frappe d’Interférence peut attaquer le lien par lequel l’entité maintient son état intangible. Si ce point cède, elle reste coincée dans une présence plus matérielle jusqu’à ce que la scène permette de reconstruire son ancrage.","groupe_actuel":"Héritages azménoriens › Technomagie azmenorienne moderne — 31 PTV › Arsenal de Rupture — 18 PTV","statut_regle":"correction","changements":"Il n''y a pas de palier I : les coûts d''origine (2, 2, 3, 3) sont conservés. Ancre d''Ombre : « tentatives immatérielles prévues » n''était défini nulle part. La liste est reprise de la Cage de Vérité (correction). Désancrage offensif : « 1/scène par cible » devient 1/scène (simplification, marquée). Cage de Vérité se prend désormais après les deux talents du palier II (avant, il fallait seulement l''Ancre)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_croix_d_emphyrra_faucon_de_malachite_elye_n_autres_o', 'Croix d''Emphyrra — Faucon de Malachite (Elyë N, autres O)', NULL, '{"nature":"exile","chemin":["Doctrines, ateliers et réseaux de Vérité","Croix d''Emphyrra — Faucon de Malachite (Elyë N, autres O)"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_doctrines_ateliers_et_reseaux_de_verite', 'Doctrines, ateliers et réseaux de Vérité', NULL, '{"nature":"exile","chemin":["Doctrines, ateliers et réseaux de Vérité"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_croix_d_emphyrra_faucon_de_malachite_elye_n_autres_o_voie_du_terrain', 'Voie du Terrain', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-lire-le-terrain', 'Lire le terrain', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Examen — 1 PA — 1/scène","texte_court":"1 PA d''observation. Le MJ donne une position, une menace ou une route ; +3 à la première action qui l''exploite (1/scène).","texte_reference":"Après 1 PA d’observation, identifiez une position, menace ou route déductible du terrain. Une fois par scène, la première action de vous-même ou d’un allié qui exploite cette lecture gagne +3.","lore":"La Voie du Terrain commence par regarder ce qui est déjà là. Couvert, hauteur, passage fragile ou danger environnemental deviennent immédiatement les éléments d’une carte tactique que le Faucon construit dans sa tête.","groupe_actuel":"Croix d''Emphyrra › Faucon de Malachite — 19 PTV › Voie du Terrain — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-terrain-familier', 'Terrain familier', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Passif","texte_court":"ignorer jusqu''à −3 dus au sol, à la végétation ou à la pente, pour se déplacer et se cacher en milieu naturel.","texte_reference":"Après quelques minutes dans un’environnement naturel, ruine ou faiblement aménagé, ignorez jusqu''à -3 de malus provenant uniquement du sol, de la végétation, de l humidité, de la pente ou d''obstacles naturels ordinaires pour se déplacer et se dissimuler.","lore":"Après quelques minutes, le Faucon lit pente, végétation, humidité et obstacles comme les règles locales du mouvement. Le terrain naturel cesse alors d’être une suite de malus pour devenir un environnement déjà compris.","groupe_actuel":"Croix d''Emphyrra › Faucon de Malachite — 19 PTV › Voie du Terrain — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-se-fondre-dans-le-decor', 'Se fondre dans le décor', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif — immobile et couvert réel","texte_court":"immobile dans un couvert naturel réel, +3 en Furtivité, même contre une recherche active.","texte_reference":"Immobile dans un couvert naturel réel, bénéficiez de +3 en Furtivité contre les observateurs, y compris une recherche active. Les perceptions inadaptées ne vous trouvent pas automatiquement, mais aucun couvert n’est créé.","lore":"Immobile dans un couvert qui pourrait vraiment le cacher, le Faucon cesse d’attirer spontanément l’œil. Il ne disparaît pas ; il devient simplement l’un des nombreux détails que personne ne pense à examiner sans raison.","groupe_actuel":"Croix d''Emphyrra › Faucon de Malachite — 19 PTV › Voie du Terrain — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-preparer-l-embuscade', 'Préparer l''embuscade', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Préparation : quelques minutes — 1/scène","texte_court":"après quelques minutes, jusqu''à trois participants gagnent +3 à leur première action qui exploite l''embuscade (1/scène).","texte_reference":"Après quelques minutes de préparation, une fois par scène, jusqu’à trois participants gagnent chacun +3 sur leur première action exploitant réellement l’embuscade. Ni Surprise garantie, ni action gratuite, ni maintien du bonus si la position est devenue inutilisable.","lore":"Le Faucon transforme une position en avantage partagé avant le premier geste hostile. Chaque participant sait quel angle, couvert ou passage exploiter lorsque l’embuscade se déclenche réellement.","groupe_actuel":"Croix d''Emphyrra › Faucon de Malachite — 19 PTV › Voie du Terrain — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_croix_d_emphyrra_faucon_de_malachite_elye_n_autres_o_autonomie', 'Autonomie', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-vivre-de-peu', 'Vivre de peu', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"tenir avec très peu ; +3 aux tests de survie liés à la pénurie.","texte_reference":"Dans un’environnement offrant réellement eau, abri et ressources minimales, le personnage peut se maintenir avec beaucoup moins de nourriture, de confort et d''équipement qu''un individu ordinaire. Circonstances favorables (+3) aux tests de survie lies à la pénurie et à l''endurance quotidienne.","lore":"La tradition de Malachite apprend à ralentir les besoins et à exploiter chaque ressource disponible. Tant que l’environnement offre réellement eau, nourriture et protection minimales, le Faucon tient là où d’autres épuiseraient vite leurs réserves.","groupe_actuel":"Croix d''Emphyrra › Faucon de Malachite — 19 PTV › Autonomie — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-faire-sans', 'Faire sans', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Passif","texte_court":"ignorer jusqu''à −3 dus à un équipement de survie absent, si un substitut plausible existe.","texte_reference":"Ignorez jusqu''à -3 de malus provenant uniquement d''un équipement de survie absent ou mediocre lorsqu’un substitut naturel ou manuel plausible existe. Le Talent ne crée jamais un matériel indispensable.","lore":"L’autonomie du Faucon repose sur l’art de remplacer ce qui manque. Une branche, une pierre ou une fibre peuvent suffire lorsqu’elles remplissent réellement la fonction de l’outil absent.","groupe_actuel":"Croix d''Emphyrra › Faucon de Malachite — 19 PTV › Autonomie — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-dejouer-les-capteurs', 'Déjouer les capteurs', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Préparation : quelques minutes — durée : scène","texte_court":"masquer pour la scène une catégorie de capteurs ordinaires, avec le terrain et des matériaux réels.","texte_reference":"Après quelques minutes de préparation, masquez pour la scène une catégorie de capteurs ordinaires à l’aide du terrain et de matériaux réels. Un balayage capable de vous détecter oppose sa Perception à votre Furtivité ; aucune immunité à un capteur d’une autre catégorie.","lore":"Le Faucon de Malachite masque sa présence avec le terrain plutôt qu’avec une technologie imaginaire. Boue, roche, végétation et relief deviennent autant de moyens de casser une signature thermique, visuelle ou acoustique.","groupe_actuel":"Croix d''Emphyrra › Faucon de Malachite — 19 PTV › Autonomie — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-refuge-autonome', 'Refuge autonome', NULL, '{"nature":"exile","cout":3,"cout_actuel":2,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Préparation : 1 heure — 1/scénario","texte_court":"en une heure, un refuge pour 5 personnes pendant 3 jours, −3 à le repérer (1/scénario).","texte_reference":"En une heure, une fois par scénario, aménagez avec un site et des ressources réels un refuge pour cinq personnes pendant trois jours. Ses dispositifs de dissimulation imposent −3 aux recherches qui tentent de le repérer, sans effacer une piste directe.\nEau, nourriture et entretien ne sont pas créés ; cette capacité ne donne ni logement revendable ni revenu.","lore":"Un bon refuge n’a pas besoin d’être confortable pour être sûr. Le Faucon choisit le site, organise l’abri et efface les signes les plus évidents afin qu’un petit groupe puisse vraiment y dormir sans attirer l’attention ordinaire.","groupe_actuel":"Croix d''Emphyrra › Faucon de Malachite — 19 PTV › Autonomie — 6 PTV","statut_regle":"correction","changements":"Coût 2 → 3."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_croix_d_emphyrra_faucon_de_malachite_elye_n_autres_o_briser_l_artifice', 'Briser l''Artifice', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-dependance-critique', 'Dépendance critique', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Examen — 1 PA","texte_court":"1 PA d''inspection ; tu trouves une dépendance d''un dispositif et gagnes +3 au premier sabotage.","texte_reference":"Après 1 PA d’inspection, identifiez une dépendance accessible d’un dispositif compris et gagnez +3 au premier test de sabotage qui l’exploite. Le talent n’apprend pas les principes d’une magie ou technologie inconnue.","lore":"Une machine ou un rituel construit possède toujours quelque chose dont dépend le reste. Le Faucon observe jusqu’à voir ce point de faiblesse — alimentation, commande, liaison ou support — sans recevoir pour autant la méthode exacte pour l’abattre.","groupe_actuel":"Croix d''Emphyrra › Faucon de Malachite — 19 PTV › Briser l''Artifice — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-sabotage-minimal', 'Sabotage minimal', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Préparation : quelques minutes","texte_court":"panne temporaire et discrète sur une dépendance identifiée.","texte_reference":"Si le personnage peut atteindre la dépendance identifiee, il peut provoquer une panne temporaire avec une intervention minimale et discrété. L''effet doit rester techniquement plausible et cesse après une vraie remise en état.","lore":"Le Faucon préfère parfois le fil desserré au mur explosé. Une intervention discrète sur la bonne dépendance suffit à provoquer une panne temporaire qui ressemble à un problème technique plausible.","groupe_actuel":"Croix d''Emphyrra › Faucon de Malachite — 19 PTV › Briser l''Artifice — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-frapper-juste', 'Frapper juste', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/Scène","texte_court":"la première attaque sur une dépendance identifiée applique une Altération matérielle dès une réussite simple.","texte_reference":"Après avoir identifie une dépendance critique, la première attaque ou action de destruction qui la vise peut appliquer une Altération matérielle appropriée des une réussite ordinaire, même si la marge n''aurait pas normalement permis une Altération. Les dégâts ne sont pas augmentes.","lore":"Une dépendance reconnue transforme un coup ordinaire en sabotage précis. Le Faucon vise ce qui fait tenir l’ensemble et obtient une vraie altération même sans produire une destruction spectaculaire du reste.","groupe_actuel":"Croix d''Emphyrra › Faucon de Malachite — 19 PTV › Briser l''Artifice — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-laisser-une-cicatrice', 'Laisser une cicatrice', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Passif","texte_court":"un sabotage sur une dépendance critique exige une vraie réparation, pas un simple redémarrage.","texte_reference":"Un sabotage ou une destruction realisee en exploitant une Dépendance critique ne peut pas être effacée par une simple remise en ligne ou un redémarrage. Une réparation réelle, des pièces ou un’atelier approprié deviennent nécessaires.","lore":"Le sabotage de Malachite cherche à obliger une réparation, pas un simple redémarrage. Une fois la dépendance correctement frappée, la panne laisse une trace matérielle que quelqu’un devra réellement remettre en état.","groupe_actuel":"Croix d''Emphyrra › Faucon de Malachite — 19 PTV › Briser l''Artifice — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_croix_d_emphyrra_serpentaire_de_citrine_elye_n_autres_r', 'Croix d''Emphyrra — Serpentaire de Citrine (Elyë N, autres R)', NULL, '{"nature":"exile","chemin":["Doctrines, ateliers et réseaux de Vérité","Croix d''Emphyrra — Serpentaire de Citrine (Elyë N, autres R)"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_croix_d_emphyrra_serpentaire_de_citrine_elye_n_autres_r_exigence_de_citrin', 'Exigence de Citrine', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-standard', 'Standard', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Examen réel","texte_court":"les défauts manifestes se voient sans jet ; +3 pour chercher un vice caché dans un domaine connu.","texte_reference":"Les défauts ordinaires manifestes restent identifiables sans jet, et vous gagnez +3 pour rechercher un vice caché dans un domaine connu. Le travail doit être réellement examiné avec les moyens adaptés.","lore":"Un travail possède toujours un compromis visible pour qui connaît réellement le domaine. Citrine apprend à reconnaître immédiatement la concession la plus évidente dans un objet, une procédure ou une prestation.","groupe_actuel":"Croix d''Emphyrra › Serpentaire de Citrine — 22 PTV › Exigence de Citrine — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-preparation', 'Préparation', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Préparation","texte_court":"une action préparée à l''avance bénéficie de « Prendre son temps » quand elle est exécutée sous pression.","texte_reference":"Après avoir réellement préparé à l’avance une action non combattante précise avec les bons outils, informations et conditions, le personnage peut bénéficier de l’effet de Prendre son temps lorsqu’il exécute plus tard cette action sous pression, sans devoir alors consacrer le délai supplémentaire. La préparation doit avoir pris un temps significatif par rapport à l’action et ne se cumule pas avec un second Prendre son temps sur le même test.","lore":"Citrine considère qu’un moment de calme peut être dépensé à l’avance. Une action précisément préparée conserve plus tard les bénéfices d’un travail posé même lorsque l’exécution doit se faire sous pression.","groupe_actuel":"Croix d''Emphyrra › Serpentaire de Citrine — 22 PTV › Exigence de Citrine — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-reprise-minutieuse', 'Reprise minutieuse', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Relance — 1/scène","texte_court":"relancer un travail encore corrigeable sans tout recommencer (1/scène).","texte_reference":"Une fois par scène, après un échec non narratif sur un travail encore corrigeable, relancez le jet sans recommencer tout le temps de travail déjà investi. Conservez le second résultat ; rien d’irréversible n’est effacé.","lore":"L’échec n’oblige pas à recommencer aveuglément. Le Serpentaire reprend l’ouvrage là où il a dérivé, corrige le geste et s’autorise une véritable seconde exécution lorsque la matière le permet encore.","groupe_actuel":"Croix d''Emphyrra › Serpentaire de Citrine — 22 PTV › Exigence de Citrine — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-oeuvre-parfaite', 'Œuvre parfaite', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Préparation réelle — 1/scénario","texte_court":"une création réussie à DR 2+ gagne 2 DR de qualité (maximum 5) (1/scénario).","texte_reference":"Une fois par scénario, un travail de création ou restauration réussi à DR 2+ gagne 2 DR pour sa qualité finale, maximum DR 5, et ignore sa première défaillance due à un défaut ordinaire de fabrication. Ni invention inconnue, ni augmentation automatique des dégâts ou du prix de vente.","lore":"L’Exigence de Citrine pousse le travail jusqu’au point où le défaut ordinaire n’a plus d’excuse. Une œuvre bien réussie et suffisamment préparée ne cède pas à la première petite erreur de fabrication qui aurait pu rester cachée.","groupe_actuel":"Croix d''Emphyrra › Serpentaire de Citrine — 22 PTV › Exigence de Citrine — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_croix_d_emphyrra_serpentaire_de_citrine_elye_n_autres_r_culture_de_l_ascen', 'Culture de l''Ascendant', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-lire-le-cercle', 'Lire le cercle', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/Scène","texte_court":"le MJ dit qui détient l''influence dans un groupe et quelle tension le structure (1/scène, d''après le tableau).","texte_reference":"Après quelques minutes d''observation d''un groupe social, le MJ indique qui detient actuellement l''influence informelle la plus forte et quelle tension visible structure le groupe. Ce n''est pas une lecture de pensee.","lore":"Quelques minutes suffisent au Serpentaire pour repérer qui façonne réellement l’ambiance du groupe et quelle tension organise les autres autour de lui. Il lit des comportements, pas des pensées secrètes.","groupe_actuel":"Croix d''Emphyrra › Serpentaire de Citrine — 22 PTV › Culture de l''Ascendant — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-maitriser-les-codes', 'Maîtriser les codes', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Passif","texte_court":"pas de pénalité pour une étiquette inconnue, après une courte observation.","texte_reference":"Après une courte observation ou un briefing, le personnage ne subit pas de penalite uniquement parce qu''un milieu formel utilise des codes, un protocole ou une étiquette qui ne lui sont pas familiers. Le Talent ne donne ni statut, ni langue, ni connaissance juridique.","lore":"Citrine apprend à observer vite et à ne pas se laisser humilier par un cérémonial inconnu. Les gestes et usages d’un milieu formel deviennent assez lisibles pour éviter le faux pas sans conférer aucun rang imaginaire.","groupe_actuel":"Croix d''Emphyrra › Serpentaire de Citrine — 22 PTV › Culture de l''Ascendant — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-retourner-l-etiquette', 'Retourner l''étiquette', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"c","acces":"V/SR/R","activation":"1/scène","texte_court":"+3 à l''action sociale qui exploite une violation de protocole de l''interlocuteur (1/scène).","texte_reference":"Une fois par scène, votre prochaine action sociale exploitant une violation explicite du protocole ou d’un engagement par l’interlocuteur gagne +3.","lore":"Retourner l''étiquette donne à la présence du personnage une gravité difficile à réduire au charme ordinaire. Les mots restent les siens et la cible conserve sa volonté, mais l’émotion, le désir ou l’autorité déjà présents dans la scène deviennent soudain beaucoup plus difficiles à ignorer.","groupe_actuel":"Croix d''Emphyrra › Serpentaire de Citrine — 22 PTV › Culture de l''Ascendant — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-enfermer-dans-ses-propres-regles', 'Enfermer dans ses propres règles', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/scène","texte_court":"−3 aux actions sociales de qui rompt ouvertement un cadre accepté devant témoins (1/scène).","texte_reference":"Une fois par scène, rappelez un cadre formel réellement accepté ; une cible qui le rompt ouvertement subit −3 aux actions sociales cherchant à conserver les avantages de ce cadre auprès des témoins, pour la scène. Elle reste libre de rompre et aucune autorité étrangère au cadre n’est inventée.\nLa sanction porte sur cet échange et ce cercle, pas sur une Renommée globale ; ne se cumule pas avec une pénalité équivalente.","lore":"Le Serpentaire sait que les puissants aiment les cadres tant qu’ils pensent en bénéficier. Une fois duel verbal, protocole ou contrat accepté, Citrine rend coûteux le moment où quelqu’un tente d’en nier soudain les règles.","groupe_actuel":"Croix d''Emphyrra › Serpentaire de Citrine — 22 PTV › Culture de l''Ascendant — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_heritages_whurtens_2', 'Héritages whurtens', NULL, '{"nature":"exile","chemin":["Doctrines, ateliers et réseaux de Vérité","Héritages whurtens"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_heritages_whurtens_atelier_des_clans_whurten_n_autres_o', 'Atelier des Clans (Whurten N, autres O)', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-fiabilisation', 'Fiabilisation', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Préparation : quelques minutes","texte_court":"la première défaillance ordinaire de l''objet dans le scénario est ignorée ; en atelier, tu élimines un mode de panne pour de bon.","texte_reference":"Avec l’objet et les outils appropriés, le Whurten améliore réellement une arme, un outil, une machine ou un dispositif qu’il comprend. Après quelques minutes de préparation, la première défaillance matérielle ordinaire qui devrait affecter l’objet avant la fin du scénario est ignorée. Avec un véritable travail d’atelier, suffisamment de temps et les matériaux nécessaires, le Whurten peut corriger durablement un mode de panne identifié : l’objet devient immunisé aux échecs critiques matériels provenant de cette cause tant que la modification reste intacte. Un échec narratif de l’utilisateur reste un échec de l’action, mais ne peut plus provoquer l’enrayement, la casse ou la panne précisément éliminée. Une amélioration matériellement plausible peut également être stabilisée de façon permanente — par exemple rendre durable un revêtement ou une couche abrasive — si le travail et les ressources le permettent. Fiabilisation ne rend jamais l’objet indestructible et n’annule ni surcharge au-delà de sa conception, ni destruction externe, ni disparition physique d’un composant.","lore":"Le Whurten connaît les petits défauts qui deviennent catastrophes lorsqu’on les ignore. Quelques minutes de réglage suffisent à éliminer la première défaillance matérielle ordinaire d’un équipement compris.","groupe_actuel":"Héritages whurtens › Atelier des Clans — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-remise-en-ligne', 'Remise en ligne', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"2 PA sous pression","texte_court":"un équipement en panne mais pas détruit retrouve sa fonction de base jusqu''à la fin de la scène.","texte_reference":"Un équipement endommage ou en panne mais non détruit retrouve sa fonction de base jusqu''à la fin de la scène si le Whurten comprend la cause et peut atteindre le composant avec des outils minimalement appropriés. Un cas complexe, exotique ou catastrophique peut demander le test technique pertinent.","lore":"Un appareil blessé mais encore réparable peut être ramené à sa fonction essentielle avec des outils minimaux. Le Whurten ne prétend pas l’avoir restauré : il le remet seulement assez droit pour finir la scène.","groupe_actuel":"Héritages whurtens › Atelier des Clans — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-reglage-de-maitre', 'Réglage de maître', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Préparation : quelques minutes — durée : scène","texte_court":"après quelques minutes, +3 aux tests qui utilisent une fonction réglée, pour la scène.","texte_reference":"Après quelques minutes de réglage, une fonction précise d’un équipement donne +3 aux tests qui l’utilisent pendant une scène. Une fonction réglée par objet ; aucun cumul d’optimisations équivalentes ni hausse permanente de ses statistiques.","lore":"Le Réglage de maître concentre tout le soin de l’artisan sur une seule fonction. Jusqu’à son prochain usage important, cette partie de l’équipement travaille au mieux de ce que la mécanique réelle permet.","groupe_actuel":"Héritages whurtens › Atelier des Clans — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-fait-pour-durer', 'Fait pour durer', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Préparation longue en’atelier","texte_court":"une fois par scénario, l''objet renforcé reste fonctionnel au lieu d''être détruit, jusqu''à la fin de la scène.","texte_reference":"Renforcez un équipement avec un vrai atelier et des matériaux. Une seule création Fait pour durer active par artisan. La première fois dans un scénario que l''objet devrait devenir inutilisable ou détruit par une contrainte matérielle laissant quelque chose de reparable, il reste au contraire lourdement endommage mais fonctionnel jusqu''à la fin de la scène. Il exige ensuite une vraie réparation. N''empêche pas une annihilation totale.","lore":"L’Atelier des Clans construit pour que la première panne grave ne soit pas la dernière. Une pièce renforcée peut rester fonctionnelle malgré un dommage qui l’aurait normalement rendue inutilisable, au prix d’une vraie réparation reportée.","groupe_actuel":"Héritages whurtens › Atelier des Clans — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_heritages_whurtens_iron_law_whurten_n_autres_o', 'Iron Law (Whurten N, autres O)', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-interface-de-verite', 'Interface de Vérité', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif — augmentation fonctionnelle requise","texte_court":"un implant qui remplace l''organe nécessaire à un talent racial passif en garde l''accès.","texte_reference":"Liez un Talent racial passif acquis à une augmentation réellement installée qui reproduit sa fonction biologique nécessaire. Ce support conserve l’accès seulement tant que l’implant fonctionne ; aucune autre capacité ni greffe n’est accordée.","lore":"Une augmentation qui remplace réellement un organe peut aussi devenir le support d’un héritage qui dépendait de cet organe. L’Iron Law ne crée rien : elle reconnaît seulement une équivalence fonctionnelle assez fidèle pour que le Talent racial continue d’exister.","groupe_actuel":"Héritages whurtens › Iron Law — 10 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-stabilite-augmentique', 'Stabilité augmentique', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"−1 Stress augmentique par implant.","texte_reference":"Chaque augmentation cybermécanique intégrée génère 1 point de Stress augmentique en moins, minimum zéro par implant. La Charge et les autres sources de Stress restent inchangées ; avec la Stabilité augmentique de Réalité, seule la meilleure réduction totale s’applique.","lore":"Le corps whurten tolère mieux que beaucoup la présence constante de mécanique intégrée. L’augmentation cesse d’être une intrusion permanente aussi stressante, sans rendre le porteur indifférent aux autres sources de surcharge augmentique.","groupe_actuel":"Héritages whurtens › Iron Law — 10 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-redondance-integree', 'Redondance intégrée', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Reaction - 1/Scène","texte_court":"une fonction d''implant neutralisé tient jusqu''à la fin du prochain round (1/scène, d''après le tableau).","texte_reference":"Lorsqu’une augmentation devient inutilisable à cause d''une panne, de dégâts, d''un brouillage, d''une surcharge ou d''une dysfonction, maintenez une de ses fonctions principales jusqu''à la fin du prochain round. Impossible si la pièce a physiquement disparu.","lore":"L’augmentation whurtenne pense déjà à sa propre panne. Lorsqu’un élément cesse de répondre sans être détruit, un circuit ou mécanisme de secours tient encore la fonction principale le temps d’un dernier round utile.","groupe_actuel":"Héritages whurtens › Iron Law — 10 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-surcadence', 'Surcadence', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"c","acces":"V/SR/R","activation":"1/scène","texte_court":"+3 avec une fonction augmentique ; elle ne devient Surchargée que sur un échec narratif (1/scène).","texte_reference":"Une fois par scène, un test exploitant une fonction augmentique gagne +3. Cette fonction ne devient Surchargée que sur un échec narratif ; dans ce cas, dix minutes de maintenance ou la fin de la scène restent nécessaires.","lore":"L’Iron Law autorise une fonction cybermécanique à donner tout ce qu’elle possède maintenant, quitte à l’épuiser ensuite. Le test gagne en efficacité et la pièce passe immédiatement dans un état qui exige repos ou maintenance.","groupe_actuel":"Héritages whurtens › Iron Law — 10 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-architecture-resiliente', 'Architecture résiliente', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Réaction — 1 PA — 1/scénario","texte_court":"réaction, 1 PA ; trois implants touchés par le même incident tiennent jusqu''à la fin de la scène (1/scénario).","texte_reference":"Une fois par scénario, pour 1 PA en Réaction, maintenez les fonctions principales de jusqu’à trois augmentations encore physiquement présentes qu’un même incident devrait neutraliser, jusqu’à la fin de la scène. La panne s’applique ensuite et nécessite sa réparation ; aucune pièce annihilée n’est remplacée.","lore":"L’Iron Law exige qu’une augmentation garde au moins ce pour quoi elle a été installée. Même abîmée, elle peut maintenir sa fonction principale jusqu’à la fin de la scène avant que la panne véritable ne réclame enfin sa dette.","groupe_actuel":"Héritages whurtens › Iron Law — 10 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_ligue_des_quatre_empereurs_ashyll_n_autres_r', 'Ligue des Quatre Empereurs (Ashyll N, autres R)', NULL, '{"nature":"exile","chemin":["Doctrines, ateliers et réseaux de Vérité","Ligue des Quatre Empereurs (Ashyll N, autres R)"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_ligue_des_quatre_empereurs_ashyll_n_autres_r_empire_invisible', 'Empire invisible', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-societe-ecran', 'Société écran', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/Scénario - préparation : quelques heures","texte_court":"tu sais mobiliser une structure juridique de la Ligue qui existe déjà ; les vérifications ordinaires s''y arrêtent (enquête à 18 pour remonter) (1/scénario).","texte_reference":"Avec accès aux réseaux de la Ligue, creez ou mobilisez une structure juridique crédible pour une opération : société, association, fonds, structure patrimoniale ou équivalent. Les verifications administratives ordinaires aboutissent à cette structure et non directement au personnage. Remonter jusqu’àu bénéficiaire réel exige une vraie enquête, difficulté typique 18.","lore":"Une opération reçoit une façade administrative plausible : société, association, fonds ou structure patrimoniale. Les vérifications routinières rencontrent d’abord cette entité réelle plutôt que le bénéficiaire qu’elle protège.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Ligue des Quatre Empereurs — 14 PTV › Empire invisible — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-acquisition-silencieuse', 'Acquisition silencieuse', NULL, '{"nature":"exile","cout":2,"cout_actuel":1,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Transaction réelle","texte_court":"tu fais passer un achat réel par des intermédiaires ; −3 aux enquêtes qui te relient à la transaction. Le paiement reste dû.","texte_reference":"Une acquisition réelle peut passer par des intermédiaires pour masquer votre identité au vendeur et imposer −3 aux enquêtes cherchant à vous relier à cette transaction. Le paiement reste dû et les preuves directes ne disparaissent pas.\nLe malus ne s’ajoute pas à une autre dissimulation substantiellement équivalente sur le même test. Pas de fausse annulation d’une trace financière existante.","lore":"L’Empire invisible peut acheter ou louer légalement sans montrer immédiatement qui bénéficiera réellement du bien. La transaction existe, est payée et laisse des traces, mais celles-ci s’arrêtent d’abord sur les intermédiaires du réseau.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Ligue des Quatre Empereurs — 14 PTV › Empire invisible — 7 PTV","statut_regle":"correction","changements":"Coût 1 → 2."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-capital-mobilise', 'Capital mobilisé', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"1/Scénario","texte_court":"un bien légal que tu peux payer est disponible dans la journée, par les circuits de la Ligue (1/scénario).","texte_reference":"Si le personnage possède réellement les ressources nécessaires pour un bien ou service légal, non unique et disponible sur le marché, la Ligue élimine les lenteurs ordinaires de recherche, de mise en relation et de paperasse : il devient accessible dans la journee. Le Talent n''obtient ni prototype unique, ni matériel interdit, ni objet que le personnage ne peut payer.","lore":"Quand les fonds existent déjà, la Ligue sait éliminer le temps perdu à trouver le bon vendeur et à remplir les formalités ordinaires. Le marché ne crée pas l’objet : il cesse simplement d’opposer ses lenteurs habituelles.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Ligue des Quatre Empereurs — 14 PTV › Empire invisible — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-portefeuille-cloisonne', 'Portefeuille cloisonné', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/scénario","texte_court":"trois structures tenues ; si l''une est compromise, tu bascules l''opération sur une autre (1/scénario).","texte_reference":"Conservez trois structures écrans indépendantes ; une fois par scénario, la compromission de l’une permet de basculer une opération encore transférable vers une autre déjà établie. Aucun actif saisi, contrat bloqué ou identité démasquée n’est effacé.","lore":"Plusieurs structures écrans restent volontairement étrangères les unes aux autres. Compromettre une société ne révèle pas automatiquement les autres, chacune constituant une piste juridique différente à reconstruire.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Ligue des Quatre Empereurs — 14 PTV › Empire invisible — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_ligue_des_quatre_empereurs_ashyll_n_autres_r_doctrine_du_levier', 'Doctrine du levier', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-pression-latente', 'Pression latente', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/Scénario - préparation","texte_court":"avec une ressource ou une faveur réelle, tu perturbes une dépendance d''une cible locale (fournisseur, bailleur, client…) (1/scénario).","texte_reference":"Identifiez une dépendance réelle de la cible - fournisseur, bailleur, financeur, transporteur, client important, assureur, prestataire, lieu ou intermédiaire. Avec une ressource, faveur ou dépense appropriée, la Ligue peut perturber temporairement cette dépendance à l''échelle d''un individu, commerce, petite organisation ou antenne locale. Le Talent ne permet pas de couper une infrastructure regionale par simple declaration.","lore":"Le pouvoir de la Ligue vient de ce dont les autres dépendent réellement : bailleur, fournisseur, client, financeur. Identifier ce point puis le perturber crée une menace concrète sans inventer une dette ou une influence qui n’existait pas.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Ligue des Quatre Empereurs — 14 PTV › Doctrine du levier — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-menace-reversible', 'Menace réversible', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Passif","texte_court":"une Pression latente peut rester suspendue, puis être activée ou levée une fois.","texte_reference":"Une Pression latente préparée peut rester suspendue pendant le scénario. Le personnage peut l''activer ou la lever une fois lorsque ses intermédiaires peuvent raisonnablement recevoir l''ordre. Aucun nouveau test n''est nécessaire. La cible reste libre de refuser la négociation.","lore":"Une bonne pression économique ou logistique n’a pas besoin d’être déclenchée immédiatement. La Ligue sait la laisser suspendue puis l’activer ou la lever au moment utile, comme une main déjà posée sur l’interrupteur.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Ligue des Quatre Empereurs — 14 PTV › Doctrine du levier — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-etranglement', 'Étranglement', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/Scénario","texte_court":"deux pressions indépendantes sur la même cible, ou une pression sur une antenne locale d''une grande organisation.","texte_reference":"Avec des ressources significatives, préparez deux Pressions latentes indépendantes reposant sur deux dépendances differentes contre la même cible. Neutraliser l''une ne neutralise pas l''autre. Alternativement, utilisez une seule pression contre une antenne locale ou branche limitée d''une grande organisation, jamais l''organisation mondiale entiere.","lore":"La Ligue des Quatre Empereurs ne dépend jamais d’un seul levier. Deux dépendances différentes peuvent être mises sous pression afin qu’une cible ne retrouve pas toute sa liberté en neutralisant seulement la première.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Ligue des Quatre Empereurs — 14 PTV › Doctrine du levier — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_syndicat_de_jade_ashyll_et_thulkar_n_autres_o', 'Syndicat de Jade (Ashyll et Thulkar N, autres O)', NULL, '{"nature":"exile","chemin":["Doctrines, ateliers et réseaux de Vérité","Syndicat de Jade (Ashyll et Thulkar N, autres O)"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_syndicat_de_jade_ashyll_et_thulkar_n_autres_o_reseau_de_jade', 'Réseau de Jade', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-le-bon-intermediaire', 'Le bon intermédiaire', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/Scénario","texte_court":"là où le Syndicat est implanté, tu sais trouver et aborder l''intermédiaire du milieu qui existe pour un service ; il ne travaille pas gratuitement (1/scénario).","texte_reference":"Dans une zone ou le Syndicat possède une présence, obtenez un contact concret capable de mettre en relation le personnage avec une catégorie ordinaire de service clandestin ou de personne du milieu. Le contact existe ; il n''est pas oblige d''accepter gratuitement.","lore":"Dans une zone tenue par le Syndicat, il existe presque toujours quelqu’un qui sait qui appeler. Le bon intermédiaire ouvre la relation vers un service clandestin ordinaire, mais reste libre de négocier son aide.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Réseau de Jade — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-faire-courir-le-bruit', 'Faire courir le bruit', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Diffusion : quelques heures — 1/scène","texte_court":"une information circule dans le réseau ; après quelques heures, tu apprends le premier intéressé et sa réaction publique (1/scène).","texte_reference":"Une fois par scène, faites circuler une information dans une portion réelle du réseau ; après quelques heures, le relais rapporte un premier intéressé et sa réaction publique s’il y en a. Ni adhésion imposée, ni intention secrète révélée.","lore":"Une rumeur confiée au Syndicat prend les chemins de ceux qui ont réellement intérêt à l’entendre. Quelques heures suffisent à la diffuser dans le milieu ciblé, sans garantir ni crédulité ni réaction favorable.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Réseau de Jade — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-canal-mort', 'Canal mort', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Préparation — durée : scénario","texte_court":"correspondance clandestine par des relais réels pour le scénario, −3 aux surveillances qui veulent relier ses interlocuteurs.","texte_reference":"Établissez pour le scénario une correspondance clandestine par relais réels, imposant −3 aux surveillances qui cherchent à relier ses interlocuteurs. Point mort reste le dépôt ou échange ponctuel ; une preuve directe ou un relais compromis peut toujours révéler le canal.","lore":"Le Réseau de Jade entretient des voies de communication qui ne supposent pas de contact direct. Boîte morte, relais ou dépôt transmettent l’information tout en obligeant une enquête sérieuse à reconstruire les deux extrémités.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Réseau de Jade — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-trouver-quelqu-un-qui-sait', 'Trouver quelqu''un qui sait', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/scénario — briefing réel","texte_court":"tu sais joindre un expert réel du réseau ; son briefing donne +3 aux tests intellectuels pendant une scène. Son prix reste dû (1/scénario).","texte_reference":"Une fois par scénario, le réseau met en relation avec un expert réel d’une question rare accessible à ses membres. Un briefing effectivement obtenu donne +3 aux tests intellectuels directement fondés sur ses conseils pendant une scène ; prix et intervention sur le terrain restent séparés.","lore":"Une expertise rare circule souvent dans les marges avant de disparaître des institutions. Le Réseau de Jade peut retrouver la personne qui possède ce savoir si elle appartient réellement à son monde de contacts.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Réseau de Jade — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_syndicat_de_jade_ashyll_et_thulkar_n_autres_o_garde_de_jade', 'Garde de Jade', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-feu-masque', 'Feu masqué', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"un tir depuis une position cachée ne trahit pas automatiquement le tireur.","texte_reference":"Lors de la première attaque à distance effectuée depuis une position réellement dissimulée ou difficile a localiser, le tir ne révèle pas automatiquement la position exacte du tireur. Les observateurs doivent disposer d''indices ou reussir une recherche appropriée.","lore":"Un tir depuis une position préparée n’indique pas automatiquement le point exact d’où il est parti. Écho, couverture et choix de l’angle obligent les observateurs à chercher le tireur au lieu de le recevoir gratuitement avec le coup de feu.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Garde de Jade — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-tirer-et-decrocher', 'Tirer et décrocher', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Après tir et rupture de vue — 1/round","texte_court":"après un tir puis une rupture de ligne de vue, tu te dissimules sans PA supplémentaire (1/round).","texte_reference":"Une fois par round, après un tir puis une rupture réelle de ligne de vue, tentez de vous dissimuler sans PA supplémentaire. Le déplacement et le tir restent payants, et il faut un couvert où disparaître.","lore":"La Garde ne reste pas dans le couvert qu’elle vient de révéler. Après le tir, le combattant glisse vers une autre protection ou hors de l’axe avant que l’adversaire n’ait entièrement recentré sa réponse.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Garde de Jade — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-feu-croise', 'Feu croisé', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"1/round","texte_court":"+3 à une attaque à distance quand un allié menace la même cible sous un angle distinct.","texte_reference":"Si un’allié menace ou attaque la même cible depuis un’angle réellement distinct, une attaque à distance du personnage contre cette cible peut bénéficier de circonstances favorables (+3). Deux tireurs empiles dans le même axe ne constituent pas un feu croisé.","lore":"Deux angles réellement distincts obligent la cible à diviser son attention. La Garde de Jade transforme cette géométrie en avantage de tir plutôt que de considérer deux armes alignées comme un faux feu croisé.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Garde de Jade — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-zone-de-mort', 'Zone de mort', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/Scène - préparation : Viser ou position équivalente","texte_court":"tu couvres un passage ; la première cible hostile qui y entre est attaquée en réaction sans PA supplémentaire (1/scène).","texte_reference":"Designez une zone étroite ou un passage que le tireur couvre réellement. La première cible hostile qui y entre ou s''y expose avant le prochain tour du tireur peut être attaquée immédiatement en Reaction sans PA supplémentaire. Une seule attaque ; si la ligne de tir est rompue, l''effet est perdu.","lore":"Un passage étroit peut devenir promesse de tir. La Garde choisit l’endroit, garde sa ligne et attend que la première cible hostile s’y expose pour déclencher la réaction préparée.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Garde de Jade — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_syndicat_de_jade_ashyll_et_thulkar_n_autres_o_contrebande_de_jade', 'Contrebande de Jade', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-point-mort', 'Point mort', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Préparation","texte_court":"tu connais les procédures de dépôt sans rencontre du Syndicat là où il est présent.","texte_reference":"Dans une zone couverte par le Syndicat, établissez un point de retrait, dépôt ou protocole permettant un echange sans rencontre directe. Une surveillance occasionnelle ne relie pas automatiquement les deux parties.","lore":"Le Syndicat sait créer un rendez-vous où personne ne rencontre directement personne. Dépôt, retrait ou protocole sépare les deux parties et oblige une surveillance à comprendre le mécanisme avant de les relier.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Contrebande de Jade — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-route-grise', 'Route grise', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/scène","texte_court":"tu sais repérer une route existante qui contourne un contrôle ordinaire ; +3 au premier passage (1/scène).","texte_reference":"Une fois par scène, identifiez une route réellement existante qui contourne un contrôle ordinaire et gagnez +3 au premier test de passage qui l’exploite. Ni secteur hermétique franchi ni contrôle militaire majeur automatiquement annulé.","lore":"Checkpoint et contrôle urbain ont souvent des angles morts administratifs ou physiques. Le réseau de Jade connaît les détours qui existent réellement et les exploite sans prétendre traverser une zone parfaitement fermée.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Contrebande de Jade — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-couverture-logistique', 'Couverture logistique', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Transport préparé","texte_court":"un transport préparé avec le réseau impose −3 à la fouille de son contenu.","texte_reference":"Un transport clandestin préparé avec le réseau impose −3 aux tests de fouille ou détection de son contenu correctement dissimulé. Une preuve directe ou un moyen de contrôle réellement incompatible avec la cache reste efficace.","lore":"La Contrebande de Jade prépare le transport pour qu’une inspection ordinaire ne tombe pas par hasard sur ce qui est caché. Une fouille ciblée reste dangereuse, précisément parce que la cargaison existe réellement quelque part.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Contrebande de Jade — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-passage-de-jade', 'Passage de Jade', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/Scénario","texte_court":"tu sais faire passer une personne ou une cargaison par les filières du Syndicat, si une route existe. Le prix ou la dette restent dus (1/scénario).","texte_reference":"Dans une zone ou le Syndicat possède une présence, organisez le passage d''une personne ou d''une cargaison raisonnable à travers un secteur fortement contrôle. Sauf secteur totalement hermétique, une route existe. Le prix, la dette ou le service reste fictionnellement exigible. Ce n''est pas une téléportation.","lore":"Dans un territoire couvert par le Syndicat, il existe presque toujours quelqu’un qui connaît la voie moins visible. Le réseau organise le passage d’une personne ou d’une cargaison tant que le secteur n’est pas physiquement hermétique.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Contrebande de Jade — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_syndicat_de_jade_ashyll_et_thulkar_n_autres_o_courtage_occulte', 'Courtage occulte', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-garantie-de-jade', 'Garantie de Jade', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Préparation","texte_court":"transaction sous arbitrage du Syndicat ; rompre l''accord crée une dette envers le réseau. Aucun effet chiffré.","texte_reference":"Organisez une transaction sous arbitrage du Syndicat. Les parties savent qu''une rupture deliberee de l''accord crée une dette ou consequence aupres du réseau. Le Talent ne force personne a accepter l''accord.","lore":"Une transaction placée sous la garantie du Syndicat transforme la trahison en dette envers le réseau entier. Personne n’est forcé d’accepter l’accord, mais ceux qui le signent savent qu’une rupture volontaire aura un prix social réel.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Courtage occulte — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-marche-ferme', 'Marché ferme', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/Scénario","texte_court":"tu sais atteindre l''acheteur ou le vendeur d''un bien occulte rare, s''il existe dans le réseau (1/scénario).","texte_reference":"Obtenez un contact concret capable d''achétér ou de vendre une catégorie rare mais non unique de bien occulte accessible au réseau.","lore":"Pour un bien occulte accessible au réseau, le plus difficile est souvent de trouver qui traite cette catégorie précise. Le Courtage ouvre la porte vers l’acheteur ou le vendeur compétent sans négocier à sa place.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Courtage occulte — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-provenance-garantie', 'Provenance garantie', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Garantie convenue avant la transaction","texte_court":"vérification d''origine d''une transaction ; remboursement contre restitution si une tromperie couverte est prouvée.","texte_reference":"Une transaction dont les courtiers acceptent explicitement la garantie fait l’objet d’une vérification de nature et d’origine ; si une tromperie couverte est ensuite démontrée, le réseau organise l’échange ou le remboursement du prix réellement payé contre restitution. Une provenance invérifiable reste annoncée comme telle.\nGarantie déclarée avant achat, jamais rétroactive. Un bien, une transaction, une indemnisation ; ni enrichissement, ni duplication, ni assurance contre destruction au combat.","lore":"Le Syndicat peut faire vérifier l’histoire commerciale d’un objet par ses courtiers. Lorsque la chaîne est solide, elle donne une provenance crédible ; lorsqu’elle ne l’est pas, le réseau sait aussi reconnaître qu’il ne peut pas garantir davantage.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Courtage occulte — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-commande-noire', 'Commande noire', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Commande réelle — 1/scénario","texte_court":"commande suivie d''un bien occulte rare réellement accessible au Syndicat, avec un prix et un délai annoncés (1/scénario).","texte_reference":"Commandez un bien occulte rare non unique réellement accessible au Syndicat, avec prix et délai annoncés avant engagement. L’achat fournit une commande suivie, pas une promesse indéfinie, et un incident de livraison réel demeure possible.","lore":"Le Courtage occulte sait demander au marché ce qui n’apparaît jamais dans les vitrines. Un objet ou matériau rare mais non unique peut remonter la chaîne si quelqu’un le possède réellement et accepte de le vendre.","groupe_actuel":"Réseaux ashylls et Syndicat de Jade › Syndicat de Jade — 32 PTV › Courtage occulte — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_hordes_thulkars_thulkar_n_autres_o', 'Hordes thulkars (Thulkar N, autres O)', NULL, '{"nature":"exile","chemin":["Doctrines, ateliers et réseaux de Vérité","Hordes thulkars (Thulkar N, autres O)"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_hordes_thulkars_thulkar_n_autres_o_formation_de_horde', 'Formation de Horde', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-deploiement-de-horde', 'Déploiement de Horde', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Première passe — 1/combat","texte_court":"à la première passe, un allié agit juste après toi. La fréquence « 1/combat » devient 1/scène (marqué).","texte_reference":"Si vous n’êtes pas Surpris et pouvez communiquer, un allié consentant éligible à la première passe du combat peut agir immédiatement après vous. Il dépense son PA normal et perd son ancien emplacement ; aucune action n’est créée.","lore":"Une Horde bien formée ne découvre pas sa position après le premier coup. Dès que l’ordre d’engagement est connu, ses membres occupent spontanément les quelques mètres qui permettront au groupe de fonctionner comme une unité.","groupe_actuel":"Hordes thulkars › Formation de Horde — commune — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-epaulement', 'Épaulement', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/round","texte_court":"+3 en Mêlée ou en Pugilat quand un allié engage la même cible depuis une autre position.","texte_reference":"Lorsqu’un’allié est lui aussi au contact de la même cible et que les deux combattants l''engagent depuis des positions réellement distinctes, une attaque de Melee ou de Pugilat du personnage peut bénéficier de circonstances favorables (+3).","lore":"Deux combattants de Horde qui engagent réellement la même cible depuis des positions distinctes créent un problème de corps et d’angles. L’un profite alors des réactions imposées par l’autre pour mieux placer sa propre attaque.","groupe_actuel":"Hordes thulkars › Formation de Horde — commune — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-releve-immediate', 'Relève immédiate', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Réaction — 1 PA — 1/round","texte_court":"réaction, 1 PA ; tu rejoins un allié neutralisé et le sécurises au contact (1/round).","texte_reference":"Pour 1 PA en Réaction, une fois par round, rejoignez un allié proche réellement neutralisé par un Déplacement normal et accomplissez une manipulation simple pour le sécuriser au contact. Aucun soin ni attaque gratuite ; l’événement ne peut être simulé par un recul volontaire.","lore":"Une place qui se vide sous la violence ne reste pas ouverte longtemps dans une Horde. Le Thulkar se jette vers l’espace abandonné ou vers le compagnon tombé afin que la ligne ne perde pas immédiatement sa forme.","groupe_actuel":"Hordes thulkars › Formation de Horde — commune — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-mouvement-de-horde', 'Mouvement de Horde', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Pendant un Déplacement payé — 1/scène","texte_court":"pendant ton Déplacement, deux alliés gagnent un Déplacement ou une Défense active gratuits (1/scène).","texte_reference":"Une fois par scène, pendant votre Déplacement payé, deux alliés initialement à 3 m choisissent chacun un Déplacement normal gratuit ou une Défense active physique gratuite avant votre prochain round. Aucun enchaînement de Mouvement de Horde et aucune attaque ou réserve de PA supplémentaire.","lore":"Le déplacement thulkar entraîne ceux qui savent suivre l’allure. Deux alliés proches se replacent dans son sillage et conservent la cohésion du groupe sans transformer ce mouvement collectif en série infinie de déplacements.","groupe_actuel":"Hordes thulkars › Formation de Horde — commune — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_hordes_thulkars_thulkar_n_autres_o_horde_divine_doctrine_d_ashorn', 'Horde Divine — Doctrine d''Ashorn', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-fixer-la-cible', 'Fixer la cible', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/round","texte_court":"après une attaque réussie, la prochaine attaque d''un allié sur la même cible gagne +3 (1/round).","texte_reference":"Après avoir reussi une attaque, désignez un’allié capable de percevoir l''action. Sa prochaine attaque contre la même cible avant le prochain tour de celle-ci peut bénéficier de circonstances favorables (+3). Une cible ne peut porter qu''un Fixer la cible à la fois.","lore":"Ashorn apprend à transformer le premier coup en information pour le suivant. Une cible déjà touchée est désignée aux autres, et l’allié qui frappe dans cette fenêtre sait exactement quelle ouverture vient d’être créée.","groupe_actuel":"Hordes thulkars › Horde Divine — Doctrine d''Ashorn — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-riposte-d-ashorn', 'Riposte d''Ashorn', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Reaction - 1/Scène","texte_court":"après une Défense active réussie au contact, attaque immédiate sans PA supplémentaire (1/scène, d''après le tableau).","texte_reference":"Après avoir reussi une Défense active contre une attaque de Melee ou de Pugilat, effectuez immédiatement une attaque normale de Melee ou de Pugilat contre l''attaquant sans PA supplémentaire, s''il est a portée.","lore":"Pour Ashorn, une parade réussie est déjà le début d’une contre-offensive. L’assaillant qui vient de se découvrir reçoit immédiatement la réponse du combattant avant d’avoir reconstruit sa garde.","groupe_actuel":"Hordes thulkars › Horde Divine — Doctrine d''Ashorn — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-plan-de-bataille', 'Plan de bataille', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Préparation : quelques minutes — 1/scène","texte_court":"trois participants fixent chacun une action ; la première exécution gagne +3 (1/scène).","texte_reference":"Après quelques minutes de préparation, une fois par scène, trois participants définissent chacun une action de leur plan ; la première exécution pertinente gagne +3. Une situation qui rend le rôle caduc annule ce bonus, sans relance ou action gratuite.","lore":"La Horde Divine aime les plans assez simples pour survivre au début d’une bataille. Chaque participant connaît sa première fonction et bénéficie de cette préparation tant que le terrain n’a pas rendu le rôle prévu absurde.","groupe_actuel":"Hordes thulkars › Horde Divine — Doctrine d''Ashorn — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_hordes_thulkars_thulkar_n_autres_o_horde_des_marais_doctrine_de_la_reussit', 'Horde des Marais — Doctrine de la Réussite', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-mauvais-moment', 'Mauvais moment', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/round","texte_court":"un adversaire te rate au contact ; ta prochaine attaque contre lui gagne +3 (1/round).","texte_reference":"Lorsqu’un’adversaire rate une attaque de Melee ou de Pugilat contre le personnage, la prochaine attaque du personnage contre lui avant la fin du round peut bénéficier de circonstances favorables (+3). Aucune Défense active n''est nécessaire.","lore":"Rater une attaque au contact contre un combattant des Marais, c’est lui offrir exactement le flottement qu’il attend. Sa prochaine réponse profite de cette posture ouverte sans exiger qu’il ait lui-même esquivé activement.","groupe_actuel":"Hordes thulkars › Horde des Marais — Doctrine de la Réussite — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-frapper-ou-ca-cede', 'Frapper où ça cède', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/round","texte_court":"+3 à une action qui exploite une cible Tendue (par ses blessures) ou Paniquée (1/round).","texte_reference":"Lorsqu’une cible est déjà Tendu ou pire à cause de ses blessures, ou Paniquee, une action qui exploite directement cette faiblesse - attaque, pression, poursuite ou action comparable - peut bénéficier de circonstances favorables (+3). Le bonus ne s''applique pas a toute interaction’avec la cible.","lore":"La Horde des Marais ne gaspille pas une faiblesse déjà visible. Blessure, panique ou épuisement deviennent le point où pression, poursuite ou attaque doivent concentrer leur effort pour faire basculer l’adversaire.","groupe_actuel":"Hordes thulkars › Horde des Marais — Doctrine de la Réussite — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-pas-mourir-pour-rien', 'Pas mourir pour rien', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Réaction gratuite — 1/scène","texte_court":"après avoir franchi un seuil de blessure, repli ou Défense active gratuits (1/scène).","texte_reference":"Une fois par scène, après une attaque qui vous fait franchir un seuil de blessure sans vous neutraliser, choisissez le repli gratuit déjà prévu ou une Défense active physique gratuite avant la fin de votre prochain round. Les dégâts initiaux et les limites physiques restent appliqués.","lore":"Quand la blessure franchit un seuil critique, la doctrine ne demande pas de rester héroïquement au mauvais endroit. Le Thulkar utilise le choc pour décrocher vers une position plus sûre avant que la menace ne termine le travail.","groupe_actuel":"Hordes thulkars › Horde des Marais — Doctrine de la Réussite — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-la-reussite-appelle-la-reussite', 'La réussite appelle la réussite', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Après réussite déterminante — 1/scène","texte_court":"après une mise à l''Agonie ou une réussite opposée à DR 3+, +1 PA avant la fin du round (1/scène).","texte_reference":"Une fois par scène, après une mise à l’Agonie adverse ou une réussite opposée déterminante à DR 3+, gagnez 1 PA utilisable pour toute action autorisée avant la fin du round. Il suit une fenêtre d’action normale, ne modifie pas l’Initiative et ne se cumule pas avec un autre gain direct de PA.","lore":"Une victoire nette produit de l’élan plutôt qu’une pause. Quand le Thulkar vient de faire tomber un adversaire ou de réussir largement une opposition décisive, il utilise immédiatement ce rythme pour se déplacer, viser ou recharger.","groupe_actuel":"Hordes thulkars › Horde des Marais — Doctrine de la Réussite — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_hordes_thulkars_thulkar_n_autres_o_horde_fantome_doctrine_de_l_integration', 'Horde Fantôme — Doctrine de l''Intégration', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-ancrage-de-realite', 'Ancrage de Réalité', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"+3 pour résister à une transition V/SR/R forcée.","texte_reference":"Circonstances favorables (+3) pour resister à un effet qui cherche explicitement a forcer le personnage a changer d''état V/SR/R ou à l''empecher de choisir sa propre transition. Ce Talent ne protege pas contre un capteur qui voit à travers le Voilé : le Fantome reste Voilé, mais le capteur voit ce qu''il est.","lore":"La Horde Fantôme apprend à tenir son état face aux forces qui veulent le modifier. Révélation ou dissimulation choisie devient une position intérieure qu’une pression extérieure doit réellement vaincre.","groupe_actuel":"Hordes thulkars › Horde Fantome — Doctrine de l''Intégration — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-identite-cloisonnee', 'Identité cloisonnée', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V","activation":"Passif — identité réellement entretenue","texte_court":"(V) une identité civile entretenue impose −3 aux enquêtes qui la relient à ta vie de Vérité.","texte_reference":"Votre identité civile réellement entretenue impose −3 aux enquêtes qui cherchent à la relier à votre Horde ou à votre vie de Vérité. Une preuve directe reste une preuve ; aucun faux document, argent ou casier vierge n’apparaît.","lore":"L’identité de Réalité n’est pas un faux nom improvisé mais une vie suffisamment complète pour ne pas mener directement vers la Horde. Travail, logement et traces administratives forment un compartiment que l’enquête doit relier par des preuves concrètes.","groupe_actuel":"Hordes thulkars › Horde Fantome — Doctrine de l''Intégration — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-disparaitre-dans-la-realite', 'Disparaître dans la Réalité', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V","activation":"1/Scène","texte_court":"(V) en foule, après une rupture de vue et sans traceur, la poursuite immédiate est cassée (1/scène).","texte_reference":"Lors d''une poursuite, si le personnage a réellement rompu la ligne de vue, se trouve dans un’environnement urbain ou fréquenté permettant de se fondre dans la population, et ne porte pas de traceur actif connu, la poursuite immediate est cassee. Les poursuivants doivent ensuite le réacquérir par enquête, surveillance, traçage, réseau ou pouvoir approprié.","lore":"Une fois la ligne de vue cassée, le Fantôme sait redevenir une personne parmi les autres. Ville, foule et routines ordinaires absorbent sa présence jusqu’à ce que ses poursuivants retrouvent une vraie piste plutôt qu’une silhouette perdue.","groupe_actuel":"Hordes thulkars › Horde Fantome — Doctrine de l''Intégration — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_hordes_thulkars_thulkar_n_autres_o_horde_des_cendres_doctrine_du_chantier', 'Horde des Cendres — Doctrine du Chantier', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-force-de-chantier', 'Force de chantier', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"pour juger si un effort collectif est possible, prendre la meilleure Vigueur du groupe, +2 par assistant (maximum +6).","texte_reference":"Pour déterminer si une action collective de soulevement, poussée, réténue, déplacement ou arrachement est physiquement possible, prenez la meilleure Vigueur du groupe et ajoutez +2 par assistant, maximum +6. Ce bonus ne s''ajoute pas au résultat du jet eventuel : il détérmine seulement si l''effort collectif peut être tente.","lore":"Les Cendres savent additionner les corps avant même de lancer le test. Une charge, une poutre ou un obstacle est évalué comme un effort collectif où les assistants rendent possible ce qu’un seul membre n’aurait jamais pu tenter.","groupe_actuel":"Hordes thulkars › Horde des Cendres — Doctrine du Chantier — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-fortification-express', 'Fortification express', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Actif — 1 PA — 1/scène","texte_court":"1 PA, un couvert partiel pour deux personnes, ou une ouverture barrée (1/scène).","texte_reference":"Pour 1 PA, une fois par scène, aménagez avec les matériaux accessibles un couvert partiel réel pour jusqu’à deux personnes ou barrez une ouverture. Le couvert donne le +3 normal dans les axes protégés et reste déplaçable ou destructible.","lore":"Meuble, plaque ou carcasse deviennent couverture quand la Horde des Cendres sait où les placer. La fortification existe réellement dans l’espace et protège jusqu’à ce que quelqu’un la déplace ou la détruise.","groupe_actuel":"Hordes thulkars › Horde des Cendres — Doctrine du Chantier — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-tenir-la-structure', 'Tenir la structure', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Réaction — 1 PA — maintien 1 PA/round","texte_court":"réaction, 1 PA ; tu retiens un élément structurel jusqu''à ton prochain round, puis 1 PA par round.","texte_reference":"Pour 1 PA en Réaction, retenez un élément structurel que vous pouvez réellement soutenir jusqu’à votre prochain round. Continuer coûte 1 PA par round et peut demander Vigueur + Athlétisme ; aucune masse impossible n’est maintenue.","lore":"Quand un mur, une porte ou un support commence à céder, le Thulkar intervient comme étai vivant. Il gagne quelques secondes pour le groupe en maintenant physiquement ce qui aurait dû s’effondrer.","groupe_actuel":"Hordes thulkars › Horde des Cendres — Doctrine du Chantier — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-chantier-de-guerre', 'Chantier de guerre', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/Scénario - préparation : quelques minutes","texte_court":"avec deux aides au moins, une tâche matérielle de plusieurs heures se fait en quelques minutes (1/scénario).","texte_reference":"Avec outils minimaux, matériaux utilisables et au moins deux personnes capables d''aider, organisez un chantier extrêmement rapide. Une tâche matérielle qui prendrait normalement plusieurs heures peut être menée en quelques minutes si elle reste techniquement possible. Le Talent ne remplace jamais une expertise indispensable absente.","lore":"La Horde des Cendres transforme une équipe et un tas de matériaux en chantier improvisé. Le temps est compressé par l’organisation, les bras et la méthode, jamais par la disparition des compétences ou des ressources nécessaires.","groupe_actuel":"Hordes thulkars › Horde des Cendres — Doctrine du Chantier — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_hordes_thulkars_thulkar_n_autres_o_horde_de_la_rose_doctrine_de_la_polyval', 'Horde de la Rose — Doctrine de la Polyvalence', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-faire-scene', 'Faire scène', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/Scène","texte_court":"tu attires l''attention ; deux alliés gagnent +3 à leurs actions discrètes jusqu''au prochain round (1/scène).","texte_reference":"Après avoir reussi une action visant réellement a attirer volontairement l''attention sur lui - performance, discours, provocation, spectacle ou demonstration - désignez jusqu''à deux alliés presents. Jusqu au début du prochain round, leurs actions dont la réussite repose réellement sur le fait de ne pas être remarques par les mêmes observateurs peuvent bénéficier de circonstances favorables (+3).","lore":"Attirer tous les regards peut devenir une couverture offerte aux autres. Le Thulkar occupe volontairement la scène par la voix, la provocation ou le spectacle afin que ses alliés trouvent plus facilement l’espace où ne pas être remarqués.","groupe_actuel":"Hordes thulkars › Horde de la Rose — Doctrine de la Polyvalence — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-contrepied', 'Contrepied', NULL, '{"nature":"exile","cout":2,"cout_actuel":1,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/scène","texte_court":"+3 à l''action qui exploite une erreur adverse préexistante sur tes capacités (1/scène).","texte_reference":"Une fois par scène, gagnez +3 à la prochaine action exploitant une erreur adverse préexistante sur vos capacités. Une simple ignorance de votre prochain geste ne suffit pas.","lore":"La Rose adore les adversaires qui croient déjà avoir compris. Lorsqu’une supposition fausse est clairement engagée dans leur comportement, le personnage peut exploiter précisément cette erreur pour produire l’effet qu’ils n’avaient pas prévu.","groupe_actuel":"Hordes thulkars › Horde de la Rose — Doctrine de la Polyvalence — 7 PTV","statut_regle":"correction","changements":"Coût 1 → 2."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-formation-croisee', 'Formation croisée', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Passif","texte_court":"en Action combinée, tu utilises la meilleure des deux Compétences, si tu as 1 ou plus dans chacune.","texte_reference":"Lorsqu’une Action combinee exige deux Compétences indispensables et que le personnage possède au moins 1 dans chacune, utilisez la meilleure des deux Compétences au lieu de la plus faible. Les autres règles de l''Action combinee restent inchangees.","lore":"La Polyvalence apprend à ne pas laisser une compétence plus faible ruiner une action qui exige deux savoir-faire déjà possédés. Les deux disciplines sont articulées autour de celle que le personnage maîtrise le mieux.","groupe_actuel":"Hordes thulkars › Horde de la Rose — Doctrine de la Polyvalence — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-interdisciplinarite', 'Interdisciplinarité', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Auto-Assistance — 1/round","texte_court":"ta propre Assistance sur une approche à deux Compétences (1/round).","texte_reference":"Une fois par round, une approche non offensive impliquant deux Compétences réellement pertinentes possédées à 1+ peut recevoir votre propre Assistance +3. Elle ne se cumule pas avec une autre Assistance et ne s’applique ni aux Défenses actives ni aux pouvoirs strictement personnels.","lore":"Une seconde compétence pertinente peut servir de soutien intérieur à la première. Le personnage rapproche deux formations réellement acquises et transforme leur intersection en aide concrète sur une tâche non offensive.","groupe_actuel":"Hordes thulkars › Horde de la Rose — Doctrine de la Polyvalence — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'exile', 'exile_servants_de_pluton_azmenorien_n_autres_r', 'Servants de Pluton (Azménorien N, autres R)', NULL, '{"nature":"exile","chemin":["Doctrines, ateliers et réseaux de Vérité","Servants de Pluton (Azménorien N, autres R)"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_servants_de_pluton_azmenorien_n_autres_r_ingenierie_xeno', 'Ingénierie xéno', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-interface-etrangere', 'Interface étrangère', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"ignorer jusqu''à −3 dus au paradigme étranger d''une interface xéno accessible.","texte_reference":"Ignorez jusqu’à −3 de malus dus au paradigme étranger pour utiliser une interface xéno réellement accessible avec la Compétence appropriée. Langue, données, chiffrement et sécurités non résolues ne disparaissent pas.","lore":"Face à une technologie inconnue, le Servant cherche ce que l’interface essaie de permettre avant de chercher le nom de son constructeur. Tant que l’appareil offre un accès réel, ses commandes peuvent être explorées avec la compétence technique adaptée.","groupe_actuel":"Héritages azménoriens › Servants de Pluton — 16 PTV › Ingenierie xeno — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-pont-de-standards', 'Pont de standards', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Préparation : quelques minutes — durable","texte_court":"une liaison durable entre deux systèmes, pour une fonction précise.","texte_reference":"Avec outils et composants adaptés, construisez une liaison durable entre deux systèmes pour une fonction précise : alimentation, données, commande ou signal. Elle demeure tant que l’adaptation matérielle est intacte, sans créer d’énergie ni de nouvelle fonction.","lore":"Alimentation, données ou commande peuvent être traduites temporairement entre deux architectures incompatibles. Le pont de Pluton ne crée aucune fonction nouvelle ; il permet simplement à deux systèmes existants de s’échanger ce qu’ils savent déjà utiliser.","groupe_actuel":"Héritages azménoriens › Servants de Pluton — 16 PTV › Ingenierie xeno — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-autonomie-forcee', 'Autonomie forcée', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Actif — 1 PA — 1/scène","texte_court":"1 PA ; une fonction locale reste disponible malgré la perte de l''infrastructure (1/scène).","texte_reference":"Pour 1 PA, une fois par scène, maintenez une fonction locale disponible d’un appareil malgré la perte de son infrastructure extérieure. Une fonction calculée ou fournie uniquement à distance, un composant absent ou une sécurité non résolue ne sont pas créés.","lore":"Pluton apprend à séparer la fonction locale de l’infrastructure dont elle dépend habituellement. Un dispositif peut continuer seul pendant une scène si tout ce qui lui faut réellement pour cette fonction est encore présent sur place.","groupe_actuel":"Héritages azménoriens › Servants de Pluton — 16 PTV › Ingenierie xeno — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-architecture-croisee', 'Architecture croisée', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Atelier : plusieurs heures — durable","texte_court":"intégrer durablement un module xéno disponible, en atelier.","texte_reference":"Intégrez durablement un module xéno réellement disponible dans un système compatible, avec atelier, pièces et temps adéquats. Sa fonction reste utilisable tant que le montage est entretenu ; aucun module, bonus doublonné ou équipement supplémentaire n’est fourni.","lore":"Les Servants de Pluton savent faire parler ensemble deux technologies qui n’ont jamais été conçues pour se rencontrer. Un module extral réellement disponible peut être intégré à un système terrestre ou d’Aèr si leurs fonctions offrent un point commun crédible.","groupe_actuel":"Héritages azménoriens › Servants de Pluton — 16 PTV › Ingenierie xeno — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'exile', 'exile_servants_de_pluton_azmenorien_n_autres_r_silence_de_pluton', 'Silence de Pluton', NULL, '{"nature":"exile","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun coût ni effet changé. Notes de transfert retirées des textes (Feu masqué, Remise en ligne, Interdisciplinarité, Ancrage de Réalité, Interface de Vérité, Stabilité augmentique). Deux signalements restent pour relecture : Interdisciplinarité vaut +3 dans le catalogue actuel alors que la V1 disait Assistance normale (+2) ; Feu masqué ressemble à la règle normale de dissimulation (la V1 le garde comme talent de 1 PTV)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-couper-la-balise', 'Couper la balise', NULL, '{"nature":"exile","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Reaction - 1/Scène","texte_court":"tu empêches une émission automatique (balise, télémétrie, appel) d''un appareil que tu tiens (1/scène, d''après le tableau).","texte_reference":"Lorsqu’un’appareil auquel le personnage a accès tente d''emettre automatiquement une balise, télémétrie, appel réseau, signal de détresse ou authentification distante, empechez cette émission précise. Un message déjà parti n''est pas efface.","lore":"Le Silence de Pluton commence par empêcher l’appareil de parler sans permission. Balise, télémétrie ou authentification automatique peuvent être coupées avant leur émission, mais jamais rappelées une fois qu’elles ont quitté le dispositif.","groupe_actuel":"Héritages azménoriens › Servants de Pluton — 16 PTV › Silence de Pluton — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-nettoyage-de-provenance', 'Nettoyage de provenance', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Préparation : quelques minutes","texte_court":"−3 aux analyses qui cherchent l''origine précise d''un équipement.","texte_reference":"Après quelques minutes de travail sur un équipement accessible, son nettoyage impose −3 aux analyses qui cherchent à identifier son origine précise. Les preuves déjà enregistrées ailleurs et les signatures physiques impossibles à modifier subsistent.","lore":"Après usage, le Servant efface ce qui raconte trop facilement d’où vient la technologie : identifiants, journaux, signatures et marquages. L’objet reste anormal ; seule son origine précise devient plus difficile à reconstruire.","groupe_actuel":"Héritages azménoriens › Servants de Pluton — 16 PTV › Silence de Pluton — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-mode-silencieux', 'Mode silencieux', NULL, '{"nature":"exile","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Actif — 1 PA — durée : scène","texte_court":"1 PA ; un appareil coupe ses émissions non indispensables pour la scène, −3 à détecter le reste.","texte_reference":"Pour 1 PA, préparez le silence d’un appareil pour la scène : ses émissions non indispensables cessent et les émissions minimales encore nécessaires imposent −3 à leur détection. Une fonction exigeant une connexion supprimée reste indisponible et les signatures non radio ne sont pas masquées.","lore":"Un appareil placé en Mode silencieux choisit son autonomie au prix de ses connexions. Tout ce qui dépend vraiment du réseau tombe avec les communications, tandis que les fonctions purement locales restent disponibles.","groupe_actuel":"Héritages azménoriens › Servants de Pluton — 16 PTV › Silence de Pluton — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'exile', 'exile-fenetre-noire', 'Fenêtre noire', NULL, '{"nature":"exile","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Actif — 1 PA — 1/scène","texte_court":"le Mode silencieux sur trois appareils préparés (1/scène).","texte_reference":"Pour 1 PA, une fois par scène, appliquez le Mode silencieux à jusqu’à trois appareils préalablement préparés et effectivement accessibles par commande. Leurs fonctions locales demeurent ; émissions indispensables, chaleur et présence physique ne deviennent pas invisibles.\nLes appareils doivent avoir été préparés avec les accès et modifications nécessaires ; pas de neutralisation à distance de machines étrangères.","lore":"Plusieurs appareils peuvent être préparés pour une opération où leurs émissions ordinaires deviendraient des témoins. Ils continuent à fonctionner localement tout en cessant de signaler spontanément leur présence au réseau extérieur.","groupe_actuel":"Héritages azménoriens › Servants de Pluton — 16 PTV › Silence de Pluton — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
